/* ═══ 대시보드 화면 ═══ (mes_work.html 가동설비 모니터링 틀)
   KPI 타일(전체·상태별 건수·합계) → 알림박스(불량 상태·기한 임박) → 그룹 필터칩 → 그룹별 헤더통계 + 상태표(뱃지·달성률·정지행 흐림)
   → 행 클릭 시 상세 + 최근 이벤트(연결된 로그 테이블) 모달. 자동갱신 주기 선택. */
function dashRoles(ts){
 const main=ts[0];const cols=colsOf(main);
 const find=(re,pred)=>cols.find(c=>re.test(c.name)&&(!pred||pred(c)));
 const status=find(/^status$|_status$|^state$|^result$|^judge$|^is_running$/i)||find(/status|state/i)||null;
 const pk=cols.find(c=>c.pk);
 const key=(pk&&pk.type!=='num'?pk:null)||find(/machine|_code$|_no$|_id$|^name$/i,c=>c.type!=='num'&&c!==status)||cols.find(c=>c.type==='text'&&c!==status)||pk||cols[0];
 const group=find(/customer|^line|group|zone|dept|department|category|plant|location|vendor|area|site/i,c=>c.type==='text'&&c!==key&&c!==status)||null;
 const time=find(/updated_at|created_at|_at$|_time$|last_|_date$/i,c=>c.type==='date'||/time|_at$/i.test(c.name))||null;
 const nums=cols.filter(c=>c.type==='num'&&!c.pk);
 const target=nums.find(c=>/target|plan|goal|capacity|std/i.test(c.name))||null;
 const actual=nums.find(c=>c!==target&&/actual|result|count|done|prod|good_qty|^qty$/i.test(c.name))||(target?nums.find(c=>c!==target):null);
 const bad=nums.find(c=>/ng|defect|fail|error|stop|down/i.test(c.name))||null;
 const texts=cols.filter(c=>c.type==='text'&&![key,group,status].includes(c));
 const ac=alertConfig(main),due=(ac.enabled&&ac.dateCol?cols.find(c=>c.name===ac.dateCol):null)||find(/due|deadline|next_|eta|planned|plan_date|_due/i,c=>c.type==='date')||null;
 /* 상태값 후보: 라벨 괄호 안 (가동/정지) 같은 표기에서 뽑는다 */
 let statusVals=[];if(status){const m=String(status.label||'').match(/\(([^)]+)\)/);if(m)statusVals=m[1].split(/[\/·,]/).map(x=>x.trim()).filter(Boolean)}
 /* 로그 테이블: 두 번째 이후 테이블 중 시각 컬럼이 있는 것 */
 const log=ts.slice(1).find(t=>colsOf(t).some(c=>c.type==='date'||/_at$|time/i.test(c.name)))||null;
 let lf=null;if(log){const lc=colsOf(log);const lk=lc.find(c=>c.name===key.name)||lc.find(c=>/code|machine|_no$|_id$|name/i.test(c.name)&&!c.pk)||lc[0];
  lf={key:lk.name,time:(lc.find(c=>c.type==='date'||/_at$|time/i.test(c.name))||{}).name||null,text:(lc.find(c=>/msg|message|event|detail|reason|content|action|remark|memo/i.test(c.name))||lc.find(c=>c.type==='text'&&c!==lk)||{}).name||null}}
 return{main,cols,status,key,group,time,nums,target,actual,bad,texts,due,statusVals,log,lf,keyLabel:key&&key.label,
  f:{key:key.name,status:status?status.name:null,group:group?group.name:null,time:time?time.name:null,target:target?target.name:null,actual:actual?actual.name:null,bad:bad?bad.name:null,due:due?due.name:null,alertDays:ac.days}};
}
function dashScreen(s,ts,loc){
 const R=dashRoles(ts);if(!R.main)return blankScreen(s,loc);const f=R.f;
 const tblCols=R.cols.filter(c=>!c.pk||c===R.key);
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css">
<style>
.body{display:flex;flex-direction:column;gap:8px;overflow:auto}
.title .live{margin-left:auto;display:flex;gap:8px;align-items:center;font-size:12px;color:#5b6b7a}
.title .dot{width:8px;height:8px;border-radius:50%;background:#2e7d32;display:inline-block}
.title .dot.off{background:#9e9e9e}
.title select{height:24px}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px}
.st{border:1px solid var(--line);background:#fff;padding:8px 10px;border-left:4px solid #9aa4b5}
.st .l{font-size:11px;color:#6b7686}.st .v{font-size:22px;font-weight:700;line-height:1.2}
.st.ok{border-left-color:#2e7d32}.st.ok .v{color:#2e7d32}
.st.ng{border-left-color:#c62828}.st.ng .v{color:#c62828}
.st.warn{border-left-color:#ef8f00}.st.warn .v{color:#b36b00}
.st.sum{border-left-color:#2f6fb5}.st.sum .v{color:#2f6fb5}
.alert{border:1px solid #f1c8c8;background:#fff5f5;padding:7px 10px;display:none}
.alert.on{display:block}.alert h3{margin:0 0 4px;font-size:12.5px;color:#b3261e}
.alert .it{display:inline-block;margin:2px 6px 2px 0;padding:2px 8px;background:#fff;border:1px solid #f1c8c8;border-radius:10px;font-size:11.5px;cursor:pointer}
.chips{display:flex;flex-wrap:wrap;gap:5px}
.chip{height:26px;padding:0 10px;border:1px solid #b7c1ca;background:#fff;border-radius:13px;font-size:12px}
.chip.on{background:var(--sel);color:#fff;border-color:var(--sel)}
.cg{border:1px solid var(--line);background:#fff}
.cg-hdr{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:6px 10px;background:linear-gradient(#f5f8fa,#e6edf2);border-bottom:1px solid var(--line)}
.cg-hdr h2{margin:0;font-size:13.5px}
.cg-hdr .s{font-size:12px;color:#456}.cg-hdr .gr{color:#2e7d32;font-weight:700}.cg-hdr .rd{color:#c62828;font-weight:700}
.badge{display:inline-block;padding:1px 8px;border-radius:9px;font-size:11px;font-weight:700;color:#fff;background:#9aa4b5}
.badge.ok{background:#2e7d32}.badge.ng{background:#c62828}.badge.warn{background:#ef8f00}
tr.dim td{color:#98a2ad;background:#fafbfc}
.prog{display:inline-block;width:70px;height:8px;background:#e6edf2;border-radius:4px;vertical-align:middle;margin-right:4px;overflow:hidden}
.prog i{display:block;height:100%;background:#2e7d32}.prog i.md{background:#ef8f00}.prog i.lo{background:#c62828}
tbody tr{cursor:pointer}
.modal-bg{position:fixed;inset:0;background:rgba(20,28,35,.38);display:none;align-items:center;justify-content:center;z-index:1000}.modal-bg.on{display:flex}
.modal{background:#fff;border:1px solid #7f8f9c;box-shadow:0 6px 24px rgba(0,0,0,.3);width:min(560px,94vw);max-height:88vh;display:flex;flex-direction:column}
.modal .t{height:30px;display:flex;align-items:center;padding:0 12px;color:#fff;background:linear-gradient(#5f7f9f,#3f5f7d);font-weight:700}.modal .t .x{margin-left:auto;cursor:pointer;font-size:16px}
.modal .bd{padding:10px 12px;overflow:auto}
.kv{display:grid;grid-template-columns:110px 1fr 110px 1fr;gap:3px 6px;font-size:12px}.kv .k{color:#6b7686}
.ev{margin-top:10px;border-top:1px solid var(--line);padding-top:6px}
.ev h4{margin:0 0 4px;font-size:12px;color:#3b556d}
.ev .row{display:flex;gap:8px;padding:3px 0;border-bottom:1px dashed #e0e6eb;font-size:11.5px}.ev .row .tm{color:#8a94a6;white-space:nowrap}
@media(max-width:680px){.kv{grid-template-columns:90px 1fr}.stats{grid-template-columns:repeat(2,1fr)}}
</style></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small>
    <span class="live"><span class="dot" id="dot"></span><span id="lastUpd">-</span> │ 갱신 <select id="ivl" onchange="setIvl()"><option value="1">1분</option><option value="5" selected>5분</option><option value="10">10분</option><option value="0">수동</option></select>
     <span id="cd"></span> <button class="btn sm" onclick="reload()">🔄 새로고침</button></span></div>
  <div class="body">
    <div class="stats" id="stats"></div>
    <div class="alert" id="alertBox"><h3 id="alertT">⚠ 확인 필요</h3><div id="alertL"></div></div>
    ${f.group?'<div class="chips" id="chips"></div>':''}
    <div id="groups"></div>
  </div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">행을 누르면 상세와 최근 이벤트가 열립니다.</span></footer>
</div>
<div class="modal-bg" id="dlg" onclick="if(event.target===this)dlg.classList.remove('on')"><div class="modal"><div class="t"><span id="dT"></span><span class="x" onclick="dlg.classList.remove('on')">×</span></div><div class="bd" id="dB"></div></div></div>
<script>
const ROWS=[],LOGS=[];window.ROWS=ROWS;window.LOGS=LOGS;
const F=${JSON.stringify(f)},LF=${JSON.stringify(R.lf)};
const CM=${JSON.stringify(R.cols)};${calcRuntimeJs()}
const COLS=${JSON.stringify(tblCols.map(c=>({n:c.name,l:c.label||c.name,t:c.type,formula:c.formula||'',unit:c.unit||'',decimals:c.decimals})))};
const NUMS=${JSON.stringify(R.nums.map(c=>({n:c.name,l:c.label||c.name})))};
const GOOD=/가동|정상|양호|완료|OK|RUN|정상가동|승인|입고|합격/i,BAD=/정지|비가동|NG|고장|알람|지연|불량|STOP|반려|취소|미점검|초과|경고/i,WARN=/점검|대기|보류|IDLE|임박|진행|검토|수리|예정/i;
const cls=v=>{v=String(v??'');return BAD.test(v)?'ng':GOOD.test(v)?'ok':WARN.test(v)?'warn':''};
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmt=n=>(n===''||n==null||isNaN(Number(n)))?(n??'-'):Number(n).toLocaleString('ko-KR');
function msg(t){message.textContent=t}
let cur='ALL',timer=null,left=0;
function boot(){render();setIvl()}
function setIvl(){clearInterval(timer);const m=+ivl.value;if(!m){cd.textContent='';return}left=m*60;cd.textContent=m+':00 후';
 timer=setInterval(()=>{left--;cd.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0')+' 후';if(left<=0){left=m*60;reload()}},1000)}
async function reload(){
 if(window.MESDB&&MESDB.online){try{const rs=await MESDB.table('${R.main.name}').select('select=*',{fresh:true});ROWS.length=0;ROWS.push(...rs);
   ${R.log?`try{const ls=await MESDB.table('${R.log.name}').select('select=*&order=${R.lf.time||R.lf.key}.desc&limit=300',{fresh:true});LOGS.length=0;LOGS.push(...ls)}catch(e){}`:''}
   dot.classList.remove('off')}catch(e){dot.classList.add('off');msg('갱신 실패: '+e.message.slice(0,80))}}
 render();lastUpd.textContent=new Date().toLocaleTimeString('ko-KR');}
const dayDiff=v=>{if(!v)return null;const a=new Date(new Date().toISOString().slice(0,10)),b=new Date(v);return Number.isFinite(+b)?Math.ceil((b-a)/864e5):null};const dueState=r=>{const d=F.due?dayDiff(r[F.due]):null;return d==null?'':d<0?'over':d<=Number(F.alertDays||0)?'soon':''};const isDue=r=>!!dueState(r);
function render(){
 const all=ROWS;all.forEach(r=>calcApplyRow(r,CM));const st=F.status;
 /* KPI */
 let h='<div class="st"><div class="l">전체</div><div class="v">'+all.length+'</div></div>';
 if(st){const vals=[...new Set(all.map(r=>r[st]).filter(v=>v!=null&&v!==''))];
  for(const v of vals)h+='<div class="st '+cls(v)+'"><div class="l">'+esc(v)+'</div><div class="v">'+all.filter(r=>r[st]===v).length+'</div></div>'}
 if(F.due){const ov=all.filter(r=>dueState(r)==='over').length,so=all.filter(r=>dueState(r)==='soon').length;if(ov)h+='<div class="st ng"><div class="l">⛔ 기한 초과</div><div class="v">'+ov+'</div></div>';if(so)h+='<div class="st warn"><div class="l">⏰ '+Number(F.alertDays||0)+'일 이내</div><div class="v">'+so+'</div></div>'}
 for(const c of NUMS.slice(0,3)){const sum=all.reduce((a,r)=>a+(Number(r[c.n])||0),0);h+='<div class="st '+(c.n===F.bad?'ng':'sum')+'"><div class="l">'+esc(c.l)+' 합계</div><div class="v">'+fmt(sum)+'</div></div>'}
 if(F.target&&F.actual){const t=all.reduce((a,r)=>a+(Number(r[F.target])||0),0),a=all.reduce((a2,r)=>a2+(Number(r[F.actual])||0),0);if(t)h+='<div class="st sum"><div class="l">달성률</div><div class="v">'+Math.round(a/t*100)+'%</div></div>'}
 stats.innerHTML=h;
 /* 알림 */
 const al=all.filter(r=>(st&&cls(r[st])==='ng')||isDue(r));
 alertBox.classList.toggle('on',!!al.length);
 alertT.textContent='⚠ 확인 필요 '+al.length+'건'+(F.due?' (이상 상태 · 기한 초과/ '+Number(F.alertDays||0)+'일 이내)':'');
 alertL.innerHTML=al.slice(0,30).map(r=>'<span class="it" onclick="openRow(\\''+esc(String(r[F.key]))+'\\')">'+esc(r[F.key])+(st?' · '+esc(r[st]):'')+(isDue(r)?' · '+esc(r[F.due]):'')+'</span>').join('');
 /* 그룹 */
 const gk=F.group;const groups={};for(const r of all){const g=gk?(r[gk]||'(미지정)'):'';(groups[g]??=[]).push(r)}
 const names=Object.keys(groups).sort((a,b)=>a.localeCompare(b,'ko'));
 if(gk){chips.innerHTML='<button class="chip '+(cur==='ALL'?'on':'')+'" onclick="pick(\\'ALL\\')">전체 ('+all.length+')</button>'+names.map(g=>'<button class="chip '+(cur===g?'on':'')+'" onclick="pick(\\''+esc(g)+'\\')">'+esc(g)+' ('+groups[g].length+')</button>').join('')}
 const show=(cur==='ALL'||!gk)?names:names.filter(g=>g===cur);
 $('groups').innerHTML=show.map(g=>{const rows=groups[g];
  const ok=st?rows.filter(r=>cls(r[st])==='ok').length:0,ng=st?rows.filter(r=>cls(r[st])==='ng').length:0;
  const hd='<div class="cg-hdr">'+(gk?'<h2>🏢 '+esc(g)+'</h2>':'')+'<span class="s">'+rows.length+'건</span>'+(st?'<span class="s gr">'+esc((rows.find(r=>cls(r[st])==='ok')||{})[st]||'정상')+' '+ok+'</span><span class="s rd">'+esc((rows.find(r=>cls(r[st])==='ng')||{})[st]||'이상')+' '+ng+'</span>':'')
   +NUMS.slice(0,2).map(c=>'<span class="s">'+esc(c.l)+' '+fmt(rows.reduce((a,r)=>a+(Number(r[c.n])||0),0))+'</span>').join('')+'</div>';
  const tb='<div class="tablewrap"><table><thead><tr>'+COLS.map(c=>'<th'+(c.t==='num'?' class="r"':'')+'>'+esc(c.l)+'</th>').join('')+(F.target&&F.actual?'<th>달성</th>':'')+'</tr></thead><tbody>'
   +rows.map(r=>{const bad=st&&cls(r[st])==='ng';let tr='<tr class="'+(bad?'dim':'')+'" onclick="openRow(\\''+esc(String(r[F.key]))+'\\')">';
    for(const c of COLS){const v=r[c.n],cv=c.formula?calcFormat(v,{type:c.t,unit:c.unit,decimals:c.decimals},true):(c.t==='num'?fmt(v):esc(v??''));tr+='<td'+(c.t==='num'?' class="r"':'')+'>'+(c.n===st?'<span class="badge '+cls(v)+'">'+esc(v||'-')+'</span>':c.formula?esc(cv):cv)+'</td>'}
    if(F.target&&F.actual){const t=Number(r[F.target])||0,a=Number(r[F.actual])||0,p=t?Math.min(100,Math.round(a/t*100)):0;tr+='<td><span class="prog"><i class="'+(p>=80?'':p>=50?'md':'lo')+'" style="width:'+p+'%"></i></span>'+(t?p+'%':'-')+'</td>'}
    return tr+'</tr>'}).join('')+'</tbody></table></div>';
  return '<div class="cg">'+hd+tb+'</div>'}).join('')||'<div class="empty">표시할 자료가 없습니다.</div>';
}
function pick(g){cur=g;render()}
function openRow(k){const r=ROWS.find(x=>String(x[F.key])===k);if(!r)return;
 dT.textContent=(F.group&&r[F.group]?r[F.group]+' · ':'')+k;
 calcApplyRow(r,CM);let h='<div class="kv">'+COLS.map(c=>'<span class="k">'+esc(c.l)+'</span><span>'+(c.n===F.status?'<span class="badge '+cls(r[c.n])+'">'+esc(r[c.n]||'-')+'</span>':c.formula?esc(calcFormat(r[c.n],{type:c.t,unit:c.unit,decimals:c.decimals},true)):esc(c.t==='num'?fmt(r[c.n]):(r[c.n]??'-')))+'</span>').join('')+'</div>';
 if(LF){const ev=LOGS.filter(l=>String(l[LF.key])===k||String(l[LF.key])===String(r[LF.key])).slice(0,20);
  h+='<div class="ev"><h4>최근 이벤트 '+ev.length+'건</h4>'+(ev.length?ev.map(l=>'<div class="row"><span class="tm">'+esc(LF.time?String(l[LF.time]).slice(0,16).replace('T',' '):'')+'</span><span>'+esc(LF.text?l[LF.text]:JSON.stringify(l))+'</span></div>').join(''):'<div style="color:#8a94a6;font-size:11.5px">이벤트 없음</div>')+'</div>'}
 dB.innerHTML=h;dlg.classList.add('on')}
window.MES={search:render,setMessage:msg};
<\/script>
<script src="mes_db.js"><\/script>
<script>(async()=>{try{await MESDB.ready}catch(e){}if(window.MESDB&&MESDB.online){await reload()}else{boot()}
 ${R.log?`try{MESDB.onChange(['${R.main.name}','${R.log.name}'],()=>reload())}catch(e){}`:`try{MESDB.onChange(['${R.main.name}'],()=>reload())}catch(e){}`}})();<\/script>
<div id="toast"></div></body></html>
`;
}
/* ═══ 엑셀 붙여넣기 등록 화면 ═══
   상단 부모키(제번) 선택 → 엑셀 표를 Ctrl+V → 제목행 자동 인식(컬럼 라벨/이름으로 매칭) → 미리보기(신규·수정·중복) → 리스트 추가 → 체크 후 등록.
   컬럼 인식 규칙을 테이블 정의에서 만들어 내므로 품목·자재·거래처 어떤 표에도 쓸 수 있다. */
function pasteRoles(ts){
 const t=ts[0];const cols=colsOf(t);
 const pk=cols.find(c=>c.pk)||null;
 const META=/created_by|created_date|updated_at|writer|reg_by|reg_date|등록자|등록일/i;
 const parent=cols.find(c=>!c.pk&&/^job_no$|^order_no$|^contract_no$|^bl_no$|^doc_no$/i.test(c.name))
   ||cols.find(c=>!c.pk&&c.req&&/_no$|_code$/.test(c.name)&&!/part|item/i.test(c.name))||null;
 const meta=cols.filter(c=>META.test(c.name));
 const body=cols.filter(c=>c!==pk&&c!==parent&&!meta.includes(c));
 const key=(body.find(c=>/part_no|item_code|part_code|code$|_no$/i.test(c.name))||body[0]||{}).name;
 return{t,pk,parent,meta,body,f:{parent:parent?parent.name:null,key}};
}
function pasteScreen(s,ts,loc){
 const R=pasteRoles(ts);if(!R.t||!R.body.length)return blankScreen(s,loc);
 const t=R.t,f=R.f;
 /* 컬럼별 인식 정규식: 라벨의 한글 낱자 사이 공백 허용 + 영문 컬럼명 */
 const rx=c=>{const lb=String(c.label||'').replace(/\(.*?\)/g,'').trim();
  const loose=x=>x.split('').map(ch=>/[가-힣a-zA-Z0-9]/.test(ch)?ch:'\\'+ch).join('\\s*');
  /* 라벨 전체 + ·,/,, 로 나눈 각 조각도 인식 (예: '두께·직경' → 두께 / 직경 도 매칭) */
  const parts=[...new Set([lb,...lb.split(/[·\/,]/)].map(x=>x.trim()).filter(x=>x.length>=1))];
  const ko=parts.map(loose);
  const en=c.name.replace(/_/g,'\\s*_?\\s*');
  return '/^\\s*('+[...ko,en].filter(Boolean).join('|')+')\\s*$/i'};
 const listCols=[...(R.parent?[R.parent]:[]),...R.body,...R.meta];
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css">
<style>
.body{grid-template-rows:auto auto minmax(0,1fr)}
.guide{padding:6px 10px;background:#f5f0ff;border:1px solid #d8cdf0;color:#5b3fa0;font-size:11.5px;line-height:1.7}
.guide b{color:#3f2a78}
.xwrap{border:1px solid var(--line);background:#fbfcfd}
.xwrap textarea{width:100%;min-height:76px;border:0;border-bottom:1px solid var(--line2);padding:7px 9px;font:12px ui-monospace,Consolas,monospace;resize:vertical;outline:0}
.xinfo{padding:5px 9px;font-size:11.5px;color:#456;border-bottom:1px solid var(--line2);background:#fff}
.xprev{max-height:190px;overflow:auto;background:#fff}
.xprev table{min-width:620px}
.xprev tr.dup td{background:#fff1f1}
.xprev tr.upd td{background:#fffaf0}
.xbar{display:flex;flex-wrap:wrap;gap:6px;align-items:center;padding:6px 9px;background:#fff8e6;border-top:1px solid #e6d3a0}
.xbar .lab{min-height:24px;padding:0 8px}
.chkcol{width:34px;text-align:center}
tbody tr.pick td{background:#eaf3ff}
tbody tr.pick.sel td{background:var(--sel)}
td.ed{padding:0}td.ed input{width:100%;height:24px;border:1px solid transparent;background:transparent;padding:0 5px}
td.ed input:focus{border-color:var(--blue);background:#fff;outline:0}
@media(max-width:880px){.xprev table{min-width:520px}}
</style></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small></div>
  <div class="body">
    <div class="guide">${R.parent?'<b>①</b> '+esc(R.parent.label||R.parent.name)+' 선택 → ':''}<b>${R.parent?'②':'①'}</b> 엑셀에서 <b>${R.body.map(c=>esc(c.label||c.name)).join('·')}</b> 복사(Ctrl+C) → 아래 칸에 <b>Ctrl+V</b> → <b>${R.parent?'③':'②'}</b> [⬇ 리스트에 추가] → 등록할 행 <b>체크</b> → [▤ 등록]
      <button class="btn sm" style="margin-left:8px" onclick="tplDown()">⤓ 서식 받기</button></div>
    <section class="xwrap">
      <div class="xbar" style="background:#eef3f8;border-top:0;border-bottom:1px solid var(--line2)">
        ${R.parent?`<span class="lab">${esc(R.parent.label||R.parent.name)}</span><input id="pKey" class="field" style="width:190px" list="dlKey" placeholder="선택 또는 입력"><datalist id="dlKey"></datalist>`:''}
        <span class="msg" id="keyMsg" style="color:#456"></span>
      </div>
      <textarea id="xText" placeholder="여기에 붙여넣기 (Ctrl+V)&#10;예) ${R.body.map(c=>c.type==='num'?'1':(c.label||c.name)).join('\t')}" oninput="xPrev()" onpaste="setTimeout(xPrev,30)"></textarea>
      <div class="xinfo" id="xInfo">붙여넣으면 읽은 결과가 여기 표시됩니다.</div>
      <div class="xprev" id="xTable"></div>
      <div class="xbar">
        ${R.meta.map(c=>`<span class="lab">${esc(c.label||c.name)}</span><input id="m_${c.name}" class="field" style="width:130px" ${c.type==='date'?'type="date"':''}>`).join('')}
        <span style="color:#6b5a2a;font-size:11.5px">${R.meta.length?'(등록 시 모든 행에 적용)':''}</span>
        <span style="margin-left:auto"></span>
        <button class="btn primary" onclick="xAdd()">⬇ 리스트에 추가</button>
        <button class="btn" onclick="xClear()">✕ 붙여넣기 지우기</button>
      </div>
    </section>
    <section class="panel">
      <div class="cap">등록 대기 · 등록된 품목 <span class="right"><input id="q" class="field" style="width:130px;height:22px" placeholder="검색" oninput="render()"> &nbsp;<span id="countText"></span></span></div>
      <div class="actions" style="border-bottom:1px solid var(--line2)">
        <label class="ck" style="padding:0 6px"><input type="checkbox" id="allChk" onchange="toggleAll(this.checked)">전체선택</label>
        <button class="btn primary" onclick="regSel()">▤ 등록</button>
        <button class="btn warn" onclick="delSel()">✖ 선택삭제</button>
        <button class="btn" onclick="addRow()">＋ 빈 행</button>
        <button class="btn" onclick="exportCsv()">▤ EXCEL</button>
      </div>
      <div class="tablewrap"><table><thead><tr><th class="chkcol"><input type="checkbox" onchange="toggleAll(this.checked)"></th><th style="width:44px">No</th>${listCols.map(c=>`<th${c.type==='num'?' class="r"':''}>${esc(c.label||c.name)}</th>`).join('')}</tr></thead><tbody id="tbody"></tbody></table></div>
    </section>
  </div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">엑셀 표를 그대로 붙여넣으면 제목행을 찾아 열을 맞춥니다.</span></footer>
</div>
<script>
const DATA=[],NEW=[];window.DATA=DATA;
const COLS=${JSON.stringify(R.body.map(c=>({k:c.name,t:c.label||c.name,n:c.type==='num'})))}.map((c,i)=>({...c,re:[${R.body.map(rx).join(',')}][i]}));
const F=${JSON.stringify(f)},PK=${JSON.stringify(R.pk?R.pk.name:null)},PKNUM=${JSON.stringify(!!(R.pk&&R.pk.type==='num'))};
const META=${JSON.stringify(R.meta.map(c=>c.name))},LIST=${JSON.stringify(listCols.map(c=>c.name))};
const T=${JSON.stringify(Object.fromEntries(colsOf(t).map(c=>[c.name,c.type])))};
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const today=()=>{const d=new Date(),z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,10)};
function msg(t){message.textContent=t}
function boot(){
 ${R.meta.map(c=>c.type==='date'?`if($('m_${c.name}'))$('m_${c.name}').value=today();`:'').join('')}
 ${f.parent?`fillKeys();`:''}render();
}
${f.parent?`function fillKeys(){const ks=[...new Set(DATA.map(r=>r[F.parent]).filter(Boolean))];
 dlKey.innerHTML=ks.map(k=>'<option value="'+esc(k)+'">').join('');
 if(!pKey.value&&ks.length)pKey.value=ks[0];
 keyMsg.textContent=ks.length?'등록된 '+ks.length+'건':'';}`:''}
/* ── 붙여넣기 파싱 ── */
function splitRows(txt){return txt.replace(/\\r/g,'').split('\\n').filter(l=>l.trim()!=='')
 .map(l=>l.indexOf('\\t')>=0?l.split('\\t'):l.trim().split(/\\s{2,}|\\s*\\|\\s*|,(?=\\S)/))}
function findHead(g){
 for(let i=0;i<Math.min(4,g.length);i++){
  const idx={};let hit=0;
  g[i].forEach((cell,j)=>{const v=String(cell).trim();if(!v)return;
   for(const c of COLS)if(idx[c.k]==null&&c.re.test(v)){idx[c.k]=j;hit++;break}});
  if(hit>=2)return{head:i,idx}}
 const idx={};COLS.forEach((c,j)=>idx[c.k]=j);return{head:-1,idx};
}
function parsed(){
 const g=splitRows($('xText').value);if(!g.length)return{g:[],rows:[],head:-1,idx:{},skip:0};
 const{head,idx}=findHead(g);const rows=[];let skip=0;
 for(let i=head+1;i<g.length;i++){
  const r={};for(const c of COLS){const j=idx[c.k];let v=j!=null?String(g[i][j]??'').trim():'';
   if(c.n){const n=Number(String(v).replace(/[^0-9.-]/g,''));v=isNaN(n)||v===''?'':n}
   r[c.k]=v}
  if(!String(r[F.key]??'').trim()){skip++;continue}
  rows.push(r)}
 return{g,rows,head,idx,skip};
}
function xPrev(){
 const{rows,head,idx,skip}=parsed();
 if(!rows.length){xInfo.textContent='붙여넣으면 읽은 결과가 여기 표시됩니다.';xTable.innerHTML='';return}
 const miss=COLS.filter(c=>idx[c.k]==null).map(c=>c.t);
 const ex=new Set(DATA.map(r=>String(r[F.key])));
 const uniq=[...new Set(rows.map(r=>String(r[F.key])))];
 const upd=uniq.filter(k=>ex.has(k)).length;
 const cnt={};rows.forEach(r=>{const k=String(r[F.key]);cnt[k]=(cnt[k]||0)+1});
 xInfo.innerHTML=(head>=0?'<span style="color:#1d6b3a">✔ '+(head+1)+'행을 제목행으로 인식':'<span style="color:#1d6b3a">✔ 제목행 없음 → '+COLS.map(c=>c.t).join('·')+' 순서로 읽음')
  +' · 대상 <b>'+rows.length+'</b>행</span> <span style="color:#456">(신규 '+(uniq.length-upd)+' · 수정 '+upd+')</span>'
  +(skip?' <span style="color:#8a6d1d">('+esc(COLS.find(c=>c.k===F.key).t)+' 빈 행 '+skip+'개 제외)</span>':'')
  +(miss.length?'<br><span style="color:#b04a4a">⚠ 제목행에서 못 찾은 열: '+miss.join(', ')+' — 빈 값으로 등록됩니다</span>':'');
 xTable.innerHTML='<table><thead><tr><th style="width:40px">No</th>'+COLS.map(c=>'<th'+(c.n?' class="r"':'')+'>'+esc(c.t)+'</th>').join('')+'</tr></thead><tbody>'
  +rows.slice(0,300).map((r,i)=>{const k=String(r[F.key]);const cls=cnt[k]>1?'dup':ex.has(k)?'upd':'';
   return '<tr class="'+cls+'" title="'+(cnt[k]>1?'중복 — 마지막 행으로 합쳐집니다':ex.has(k)?'기존 항목 수정':'신규')+'"><td>'+(i+1)+'</td>'
    +COLS.map(c=>'<td'+(c.n?' class="r"':'')+'>'+esc(r[c.k])+'</td>').join('')+'</tr>'}).join('')
  +'</tbody></table>'+(rows.length>300?'<div style="padding:5px;color:#8a94a6">… 앞 300행만 표시</div>':'');
}
function xAdd(){
 const{rows}=parsed();if(!rows.length)return msg('붙여넣은 내용이 없습니다.');
 ${f.parent?`const key=(pKey.value||'').trim();if(!key)return msg('${R.parent?esc(R.parent.label||R.parent.name):''} 을(를) 먼저 선택하세요.');`:''}
 let add=0,upd=0;
 for(const r of rows){
  const o={...r};${f.parent?`o[F.parent]=key;`:''}
  const i=DATA.findIndex(x=>String(x[F.key])===String(r[F.key])${f.parent?`&&String(x[F.parent])===key`:''});
  if(i>=0){DATA[i]={...DATA[i],...o};DATA[i]._sel=true;upd++}
  else{o._sel=true;o._new=true;if(PK&&PKNUM)o[PK]='';DATA.push(o);add++}}
 $('xText').value='';xPrev();${f.parent?'fillKeys();':''}render();
 msg('리스트에 추가 — 신규 '+add+'건 · 수정 '+upd+'건. 체크된 행을 [▤ 등록] 하세요.');
}
function xClear(){$('xText').value='';xPrev();msg('붙여넣기 칸을 지웠습니다.')}
function tplDown(){const h=COLS.map(c=>c.t);const ex=COLS.map(c=>c.n?'1':c.t+' 예시');
 const csv='\\ufeff'+[h,ex].map(a=>a.join(',')).join('\\n');
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='${slug(s.name)}_서식.csv';a.click();msg('서식을 내려받았습니다. 엑셀에서 채운 뒤 표 전체를 복사해 붙여넣으세요.')}
/* ── 리스트 ── */
function view(){const q=($('q').value||'').trim().toLowerCase();
 ${f.parent?`const key=(pKey.value||'').trim();`:''}
 return DATA.filter(r=>{${f.parent?`if(key&&String(r[F.parent]||'')!==key&&!r._new)return false;`:''}
  return !q||LIST.some(c=>String(r[c]??'').toLowerCase().includes(q))})}
function render(){
 const v=view();
 tbody.innerHTML=v.length?v.map((r,i)=>{const ix=DATA.indexOf(r);
  return '<tr class="'+(r._sel?'pick':'')+'">'
  +'<td class="chkcol"><input type="checkbox" '+(r._sel?'checked':'')+' onchange="pickRow('+ix+',this.checked)"></td>'
  +'<td>'+(i+1)+(r._new?' <span style="color:#2e7d5b;font-size:10px">新</span>':'')+'</td>'
  +LIST.map(c=>'<td class="ed'+(T[c]==='num'?' r':'')+'"><input value="'+esc(r[c]??'')+'" '+(T[c]==='num'?'type="number"':T[c]==='date'?'type="date"':'')+' oninput="edit('+ix+',\\''+c+'\\',this.value)"></td>').join('')
  +'</tr>'}).join(''):'<tr><td colspan="'+(LIST.length+2)+'" class="empty">등록된 품목이 없습니다. 엑셀에서 복사(Ctrl+C) 후 위 칸에 붙여넣으세요.</td></tr>';
 countText.textContent=v.length+'건 (선택 '+v.filter(r=>r._sel).length+')';
}
function pickRow(i,on){DATA[i]._sel=on;render()}
function toggleAll(on){view().forEach(r=>r._sel=on);allChk.checked=on;render()}
function edit(i,c,v){DATA[i][c]=T[c]==='num'?(v===''?'':Number(v)):v}
function addRow(){const o={_sel:true,_new:true};${f.parent?`o[F.parent]=(pKey.value||'').trim();`:''}DATA.push(o);render();msg('빈 행을 추가했습니다. 칸을 직접 채우세요.')}
function delSel(){const sel=DATA.filter(r=>r._sel);if(!sel.length)return msg('삭제할 행을 체크하세요.');
 if(!confirm(sel.length+'건을 목록에서 삭제할까요?'))return;
 for(let i=DATA.length-1;i>=0;i--)if(DATA[i]._sel)DATA.splice(i,1);
 render();msg(sel.length+'건 삭제했습니다.')}
async function regSel(){
 const sel=DATA.filter(r=>r._sel);if(!sel.length)return msg('등록할 행을 체크하세요.');
 const meta={};${R.meta.map(c=>`{const e=$('m_${c.name}');if(e&&e.value)meta['${c.name}']=e.value}`).join('')}
 for(const r of sel){Object.assign(r,meta);r._new=false}
 if(window.MESDB&&MESDB.online){
  const rows=sel.map(r=>{const o={};for(const c of LIST)if(r[c]!==undefined&&r[c]!=='')o[c]=r[c];
   if(PK&&r[PK]!==''&&r[PK]!=null)o[PK]=r[PK];return o});
  try{await MESDB.table('${t.name}').upsert(rows${R.pk?`,'${R.pk.name}'`:''})}catch(e){return msg('등록 실패: '+e.message.slice(0,120))}
 }
 DATA.forEach(r=>r._sel=false);allChk.checked=false;render();
 msg(sel.length+'건 등록했습니다.'+(META.length?' ('+META.map(c=>meta[c]).filter(Boolean).join(' · ')+')':''));
}
function exportCsv(){const h=LIST.map(c=>{const m=COLS.find(x=>x.k===c);return m?m.t:c});
 const csv='\\ufeff'+[h,...view().map(r=>LIST.map(c=>r[c]??''))].map(a=>a.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\\n');
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='${slug(s.name)}.csv';a.click()}
${f.parent?`pKey&&pKey.addEventListener('input',()=>{render();msg((pKey.value||'')+' 기준으로 표시합니다.')});`:''}
window.MES={search:render,save:regSel,delete:delSel,setMessage:msg};
<\/script>
<script src="mes_db.js"><\/script>
<script>
MESDB.master({page:'${slug(s.name)}:data',table:'${t.name}',pk:'${R.pk?R.pk.name:f.key}',map:${mapOf(t)},get:()=>DATA,render:()=>{${f.parent?'fillKeys();':''}render()}});
boot();
<\/script>
<div id="toast"></div></body></html>
`;
}
/* ═══ 권한관리 화면 ═══
   좌: 부서별 사용자 목록 · 우상: 사용자 상세 · 우하: 메뉴 트리 × 4권한(조회/저장/수정/삭제)
   메뉴 트리는 실제 시스템에서 APP_CONFIG.menuTree() 를, 미리보기에서는 설계도 계층을 그대로 쓴다. */
function designTree(){
 const kids=id=>D.edges.filter(e=>e.from===id&&e.kind==='contains').map(e=>N(e.to)).filter(Boolean);
 const sortY=a=>a.slice().sort((p,q)=>p.y-q.y||p.x-q.x);
 return sortY(D.nodes.filter(n=>n.type==='module')).map(m=>{
  const secs=sortY(kids(m.id).filter(n=>n.type==='section')).map(x=>({name:x.name,items:sortY(kids(x.id).filter(n=>n.type==='screen')).map(v=>v.name)}));
  const direct=sortY(kids(m.id).filter(n=>n.type==='screen')).map(v=>v.name);
  if(direct.length)secs.push({name:m.name,items:direct});
  return{name:m.name,secs};});
}
function permRoles(ts){
 const has=(t,re)=>colsOf(t).some(c=>re.test(c.name));
 const perms=ts.find(t=>has(t,/^can_view$|^can_save$/i))||ts.find(t=>/permission|perm|right/i.test(t.name));
 const pw=ts.find(t=>t!==perms&&has(t,/temp_password|initial_password/i));
 const users=ts.find(t=>t!==perms&&t!==pw&&(has(t,/^user_key$|^user_id$/i)||/user|employee|member/i.test(t.name)))||ts.find(t=>t!==perms&&t!==pw);
 const col=(t,re,d)=>{const c=t&&colsOf(t).find(x=>re.test(x.name));return c?c.name:d};
 const f={
  ukey:col(users,/^user_key$/i,null)||col(users,/^id$|^user_id$/i,'user_key'),
  uid:col(users,/^user_id$/i,null),uname:col(users,/^name$/i,'name'),
  udept:col(users,/department_name|^dept$/i,null)||col(users,/department/i,null),upos:col(users,/position_name|^position$/i,null)||col(users,/position/i,null),
  urole:col(users,/^role$/i,null),uactive:col(users,/is_active|^use_yn$/i,null),
  pkey:col(perms,/^user_key$/i,'user_key'),pmenu:col(perms,/menu_name|^menu$/i,'menu_name'),ppath:col(perms,/menu_path/i,null),
  pview:col(perms,/can_view/i,'can_view'),psave:col(perms,/can_save/i,'can_save'),pedit:col(perms,/can_edit/i,'can_edit'),pdel:col(perms,/can_delete|can_del/i,'can_delete'),
  wid:col(pw,/^user_id$/i,'user_id'),wpw:col(pw,/temp_password/i,'temp_password'),wchg:col(pw,/changed_by_user/i,null),wat:col(pw,/issued_at/i,null)};
 return{users,perms,pw,f};
}
function permScreen(s,ts,loc){
 const R=permRoles(ts);if(!R.users||!R.perms)return blankScreen(s,loc);
 const f=R.f;const ucols=colsOf(R.users);
 const HIDE=new Set([f.ukey]);
 const det=ucols.filter(c=>!HIDE.has(c.name));
 const field=c=>c.type==='bool'?`<div class="check"><input id="d_${c.name}" type="checkbox"></div>`
  :c.name===f.urole?`<select id="d_${c.name}" class="field"><option value="user">user</option><option value="admin">admin</option><option value="master">master</option></select>`
  :`<input id="d_${c.name}" class="field" ${c.type==='num'?'type="number"':c.type==='date'?'type="date"':''}>`;
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css">
<style>
.body{grid-template-columns:minmax(240px,34%) minmax(0,1fr)}
.right{min-height:0;display:grid;grid-template-rows:auto auto minmax(0,1fr);gap:7px}
.userlist{flex:1;min-height:0;overflow:auto}
.group-title{height:24px;display:flex;align-items:center;padding:0 8px;background:#edf3f7;border-bottom:1px solid #c8d3dc;color:#3b556d;font-weight:700;font-size:11.5px}
.user-row{display:grid;grid-template-columns:70px 1fr 52px;min-height:26px;border-bottom:1px solid #e0e6eb;cursor:pointer}
.user-row span{padding:5px 8px;border-right:1px solid #e0e6eb;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.user-row:hover{background:#eef6fc}.user-row.on{background:var(--sel);color:#fff}
.user-row .use{justify-self:center;font-size:11px;color:#2e7d32}.user-row .use.off{color:#c62828}
.user-row.on .use{color:#dff5e3}
.perm-head{display:grid;grid-template-columns:minmax(0,1fr) 260px;background:linear-gradient(#e7f0f7,#cadae7);border-bottom:1px solid var(--line);font-weight:700}
.perm-head>div{padding:6px 8px;border-right:1px solid #aebbc6}
.perm-list{flex:1;min-height:0;overflow:auto;background:#fff}
.perm-row{display:grid;grid-template-columns:minmax(0,1fr) 260px;min-height:26px;border-bottom:1px solid #e0e6eb;align-items:center}
.perm-row.mod{background:linear-gradient(#eef5fb,#e2edf6);font-weight:700}
.perm-row.sec{background:#f7fafc}.perm-row:hover{background:#edf6fd}
.perm-row>div{padding:4px 8px;border-right:1px solid #e0e6eb}
.perm-row .toggle{cursor:pointer;user-select:none;display:inline-block;width:14px;color:#5b6b7a}
.rights{display:flex;gap:8px}
.rights label{display:flex;align-items:center;gap:3px;cursor:pointer;white-space:nowrap;font-size:11.5px}
.rights input{margin:0}
.path{padding-left:calc(8px + var(--depth)*15px)!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.note{padding:12px;color:#7c8993}
.rolebadge{font-weight:700;font-size:10.5px;margin-left:4px}
@media(max-width:900px){.body{grid-template-columns:1fr;grid-template-rows:180px auto}.perm-head,.perm-row{grid-template-columns:minmax(0,1fr) 200px}.rights label span{display:none}}
</style></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small></div>
  <div class="body">
    <section class="panel">
      <div class="cap">사용자 목록 <span class="right" id="countText"></span></div>
      <div class="filters"><div class="lab">검색</div><input id="q" class="field" style="flex:1" oninput="renderUsers()" placeholder="이름 · 아이디 · 부서">
        <label class="ck" style="white-space:nowrap"><input type="checkbox" id="d_all" onchange="renderUsers()">미사용 포함</label></div>
      <div class="user-row" style="background:#dbe9f4;font-weight:700;color:#33506b"><span>직급</span><span>성명</span><span class="use" style="color:#33506b">사용</span></div>
      <div class="userlist" id="userList"></div>
    </section>
    <section class="right">
      <div class="panel"><div class="cap">사용자정보 <span class="right" id="selTxt">선택 없음</span></div>
        <div class="formgrid" style="border-left:0;border-top:0">
${det.map(c=>`          <div class="lab">${c.label||c.name}</div>${field(c)}`).join('\n')}
        </div>
      </div>
      <div class="actions">
        <button class="btn" onclick="refresh()">⟳ 새로고침</button>
        <button class="btn primary" onclick="saveUser()">▣ 저장</button>
        <button class="btn warn" onclick="delUser()">✖ 삭제</button>
        <button class="btn" onclick="addUser()">＋ 신규</button>
        <button class="btn" onclick="expandAll(true)">⊞ 전체펼침</button>
        <button class="btn" onclick="expandAll(false)">⊟ 접기</button>
        <button class="btn primary" id="btnPerm" onclick="savePerms()">🔒 권한저장</button>
        <button class="btn" onclick="copyPerms()">⧉ 권한복사</button>
      </div>
      <div class="panel">
        <div class="cap">권한 <span class="right" id="permCnt"></span></div>
        <div class="perm-head"><div>메뉴명</div><div class="rights">
          <label><input type="checkbox" onclick="setAll('view',this.checked)">조회</label>
          <label><input type="checkbox" onclick="setAll('save',this.checked)">저장</label>
          <label><input type="checkbox" onclick="setAll('edit',this.checked)">수정</label>
          <label><input type="checkbox" onclick="setAll('del',this.checked)">삭제</label></div></div>
        <div class="perm-list" id="permList"><div class="note">사용자를 선택하세요.</div></div>
      </div>
    </section>
  </div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">상위 메뉴를 체크하면 하위 전체에 적용됩니다. 저장/수정/삭제는 조회를 포함합니다.</span></footer>
</div>
<script>
const USERS=[],PERMS=[];window.USERS=USERS;window.PERMS=PERMS;
const F=${JSON.stringify(f)};
const UC=${JSON.stringify(det.map(c=>c.name))},UT=${JSON.stringify(Object.fromEntries(ucols.map(c=>[c.name,c.type])))};
const RIGHTS=[['view','조회'],['save','저장'],['edit','수정'],['del','삭제']];
const RC={view:F.pview,save:F.psave,edit:F.pedit,del:F.pdel};
const FALLBACK_TREE=${JSON.stringify(designTree())};
let TREE=[],sel='',openSet=new Set(),pIdx=new Map(),loadedFor=null,dirty=false;
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function msg(t){message.textContent=t}
function getTree(){try{const A=window.APP_CONFIG||window.parent.APP_CONFIG;if(A&&A.menuTree)return A.menuTree()}catch(e){}
 return (window.__TREE&&window.__TREE.length)?window.__TREE:FALLBACK_TREE}
function boot(){TREE=getTree();openSet=new Set(TREE.map(m=>m.name));renderUsers();if(USERS.length)pick(USERS[0][F.ukey])}
/* ── 사용자 목록 ── */
function deptOf(u){return (F.udept&&String(u[F.udept]||'').trim())||'부서없음'}
function renderUsers(){
 const q=($('q').value||'').trim().toLowerCase(),all=$('d_all').checked;
 const list=USERS.filter(u=>{
  if(q&&![u[F.uname],F.uid?u[F.uid]:'',F.udept?u[F.udept]:''].some(v=>String(v??'').toLowerCase().includes(q)))return false;
  if(!all&&F.uactive&&u[F.uactive]===false)return false;return true});
 const g=new Map();for(const u of list){const k=deptOf(u);if(!g.has(k))g.set(k,[]);g.get(k).push(u)}
 userList.innerHTML=g.size?[...g.entries()].sort((a,b)=>a[0].localeCompare(b[0],'ko')).map(([d,rows])=>
  '<div class="group-title">부서: '+esc(d)+' <span style="margin-left:auto;font-weight:400">'+rows.length+'명</span></div>'+
  rows.map(u=>{const off=F.uactive&&u[F.uactive]===false;const rl=F.urole?u[F.urole]:'';
   return '<div class="user-row '+(u[F.ukey]===sel?'on':'')+'" onclick="pick(\\''+esc(String(u[F.ukey]))+'\\')"><span>'+esc(F.upos?u[F.upos]||'':'')+'</span><span style="'+(off?'color:#9aa5b1;text-decoration:line-through':'')+'">'+esc(u[F.uname])+
   (rl==='master'?'<b class="rolebadge" style="color:#8e24aa">[마스터]</b>':rl==='admin'?'<b class="rolebadge" style="color:#1e5e91">[관리자]</b>':'')+'</span><span class="use'+(off?' off':'')+'">'+(off?'미사용':'사용')+'</span></div>'}).join('')
 ).join(''):'<div class="note">사용자가 없습니다.</div>';
 countText.textContent=list.length+'명';
}
function pick(k){
 if(dirty&&sel&&k!==sel&&!confirm('저장하지 않은 권한 변경이 있습니다. 이동할까요?'))return;
 if(dirty&&k!==sel){dirty=false;loadedFor=null;markDirty()}
 sel=k;const u=USERS.find(x=>String(x[F.ukey])===String(k));if(!u)return;
 for(const c of UC){const el=$('d_'+c);if(!el)continue;if(UT[c]==='bool')el.checked=!!u[c];else el.value=u[c]??''}
 selTxt.textContent=u[F.uname]+(F.uid&&u[F.uid]?' ('+u[F.uid]+')':'');
 renderPerms(true);renderUsers();msg(u[F.uname]+' 사용자정보를 표시합니다.')}
/* ── 권한 트리 ── */
function allMenus(){const o=[];for(const m of TREE){o.push(m.name);for(const sc of m.secs){o.push(m.name+'/'+sc.name);for(const i of sc.items)o.push(m.name+'/'+sc.name+'/'+i)}}return o}
function loadIdx(force){if(!force&&loadedFor===sel)return;pIdx=new Map();loadedFor=sel;
 PERMS.filter(p=>String(p[F.pkey])===String(sel)).forEach(p=>pIdx.set(p[F.pmenu],{...p}))}
function getP(menu){let p=pIdx.get(menu);
 if(!p){p={[F.pkey]:sel,[F.pmenu]:menu,[F.pview]:false,[F.psave]:false,[F.pedit]:false,[F.pdel]:false};pIdx.set(menu,p)}return p}
function cell(menu){const p=getP(menu);
 return '<div class="rights">'+RIGHTS.map(([k,l])=>'<label><input type="checkbox" data-menu="'+esc(menu)+'" data-right="'+k+'" '+(p[RC[k]]?'checked':'')+' onchange="toggleRight(this)"><span>'+l+'</span></label>').join('')+'</div>'}
function renderPerms(force){
 if(!sel){permList.innerHTML='<div class="note">사용자를 선택하세요.</div>';return}
 if(!TREE.length){permList.innerHTML='<div class="note">메뉴 구조를 읽지 못했습니다. (app_config.js 의 menuTree)</div>';return}
 loadIdx(force);const h=[];
 for(const m of TREE){const open=openSet.has(m.name);
  h.push('<div class="perm-row mod"><div class="path" style="--depth:0"><span class="toggle" onclick="toggleNode(\\''+esc(m.name)+'\\')">'+(open?'⊟':'⊞')+'</span> '+esc(m.name)+'</div>'+cell(m.name)+'</div>');
  if(!open)continue;
  for(const sc of m.secs){const sk=m.name+'/'+sc.name,so=openSet.has(sk);
   h.push('<div class="perm-row sec"><div class="path" style="--depth:1"><span class="toggle" onclick="toggleNode(\\''+esc(sk)+'\\')">'+(so?'⊟':'⊞')+'</span> '+esc(sc.name)+'</div>'+cell(sk)+'</div>');
   if(!so)continue;
   for(const it of sc.items)h.push('<div class="perm-row"><div class="path" style="--depth:2">└ '+esc(it)+'</div>'+cell(m.name+'/'+sc.name+'/'+it)+'</div>')}}
 permList.innerHTML=h.join('');
 const n=[...pIdx.values()].filter(p=>p[F.pview]||p[F.psave]||p[F.pedit]||p[F.pdel]).length;permCnt.textContent=n+'개 메뉴 허용';
}
function toggleNode(k){openSet.has(k)?openSet.delete(k):openSet.add(k);renderPerms()}
function expandAll(on){openSet=new Set();if(on)for(const m of TREE){openSet.add(m.name);for(const sc of m.secs)openSet.add(m.name+'/'+sc.name)}renderPerms()}
function applyOne(p,r,on){p[RC[r]]=on;
 if(r!=='view'&&on)p[F.pview]=true;                       /* 저장·수정·삭제는 조회를 포함 */
 if(r==='view'&&!on){p[F.psave]=p[F.pedit]=p[F.pdel]=false}}
function toggleRight(el){
 if(!sel)return msg('사용자를 먼저 선택하세요.');
 const menu=el.dataset.menu,r=el.dataset.right;applyOne(getP(menu),r,el.checked);
 if(menu.split('/').length<3)allMenus().filter(m=>m.startsWith(menu+'/')).forEach(m=>applyOne(getP(m),r,el.checked));
 dirty=true;renderPerms();markDirty();msg(menu+' 권한을 변경했습니다. [권한저장]을 누르세요.')}
function setAll(r,on){if(!sel)return msg('사용자를 먼저 선택하세요.');
 allMenus().forEach(m=>applyOne(getP(m),r,on));dirty=true;renderPerms();markDirty();
 msg('전체 메뉴의 '+RIGHTS.find(x=>x[0]===r)[1]+' 권한을 '+(on?'부여':'해제')+'했습니다.')}
function markDirty(){btnPerm.textContent=dirty?'🔒 권한저장 ●':'🔒 권한저장';btnPerm.style.background=dirty?'linear-gradient(#fff6d8,#ffe9a8)':''}
/* ── 저장 ── */
async function savePerms(){
 if(!sel)return msg('사용자를 선택하세요.');
 const u=USERS.find(x=>String(x[F.ukey])===String(sel));
 const rows=[...pIdx.values()].filter(p=>p[F.pview]||p[F.psave]||p[F.pedit]||p[F.pdel])
  .map(p=>{const o={[F.pkey]:sel,[F.pmenu]:p[F.pmenu],[F.pview]:!!p[F.pview],[F.psave]:!!p[F.psave],[F.pedit]:!!p[F.pedit],[F.pdel]:!!p[F.pdel]};
   ${f.ppath?`o[F.ppath]=String(p[F.pmenu]).split('/');`:''}return o});
 for(let i=PERMS.length-1;i>=0;i--)if(String(PERMS[i][F.pkey])===String(sel))PERMS.splice(i,1);
 PERMS.push(...rows);
 if(window.MESDB&&MESDB.online){try{
   await MESDB.rest('${R.perms.name}?'+F.pkey+'=eq.'+encodeURIComponent(sel),{method:'DELETE',headers:{Prefer:'return=minimal'}});
   if(rows.length)await MESDB.table('${R.perms.name}').upsert(rows,F.pkey+','+F.pmenu);
  }catch(e){return msg('권한 저장 실패: '+e.message.slice(0,120))}}
 dirty=false;loadedFor=null;markDirty();renderPerms(true);
 const rl=F.urole?u[F.urole]:'';
 msg(u[F.uname]+' 권한 '+rows.length+'건 저장.'+((rl==='master'||rl==='admin')?' ※ '+(rl==='master'?'마스터':'관리자')+'는 권한 설정과 무관하게 전체 메뉴를 사용합니다.':' 다음 로그인부터 적용됩니다.'))}
function copyPerms(){
 if(!sel)return msg('복사할 원본 사용자를 선택하세요.');
 const u=USERS.find(x=>String(x[F.ukey])===String(sel));
 const others=USERS.filter(x=>x[F.ukey]!==sel).map(x=>x[F.uname]).join(', ');
 const to=prompt(u[F.uname]+' 의 권한을 복사할 대상 사용자명\\n('+others+')');if(!to)return;
 const t=USERS.find(x=>String(x[F.uname]).trim()===to.trim());if(!t)return msg('해당 사용자를 찾을 수 없습니다.');
 const src=[...pIdx.values()].filter(p=>p[F.pview]||p[F.psave]||p[F.pedit]||p[F.pdel]);
 for(let i=PERMS.length-1;i>=0;i--)if(String(PERMS[i][F.pkey])===String(t[F.ukey]))PERMS.splice(i,1);
 PERMS.push(...src.map(p=>({[F.pkey]:t[F.ukey],[F.pmenu]:p[F.pmenu],[F.pview]:p[F.pview],[F.psave]:p[F.psave],[F.pedit]:p[F.pedit],[F.pdel]:p[F.pdel]})));
 msg(u[F.uname]+' → '+t[F.uname]+' 권한 '+src.length+'건 복사. '+t[F.uname]+' 선택 후 [권한저장]을 누르세요.')}
function saveUser(){
 if(!sel)return msg('사용자를 선택하세요.');
 const u=USERS.find(x=>String(x[F.ukey])===String(sel));if(!u)return;
 for(const c of UC){const el=$('d_'+c);if(!el)continue;u[c]=UT[c]==='bool'?el.checked:UT[c]==='num'?(el.value===''?'':Number(el.value)):el.value}
 if(window.MESDB&&MESDB.syncMaster)MESDB.syncMaster().catch(()=>{});
 renderUsers();msg(u[F.uname]+' 사용자 정보를 저장했습니다.')}
function addUser(){
 const nm=prompt('새 사용자 이름');if(!nm)return;
 const key=prompt('사용자키 (예: 부서코드_이름)',(F.udept?'':'')+nm);if(!key)return;
 if(USERS.some(x=>String(x[F.ukey])===key))return msg('이미 있는 사용자키입니다.');
 const o={[F.ukey]:key,[F.uname]:nm};if(F.uactive)o[F.uactive]=true;if(F.urole)o[F.urole]='user';
 USERS.push(o);if(window.MESDB&&MESDB.syncMaster)MESDB.syncMaster().catch(()=>{});
 renderUsers();pick(key);msg(nm+' 추가 — 상세를 채우고 [저장], 아래 트리에서 권한을 주고 [권한저장]')}
async function delUser(){
 if(!sel)return msg('삭제할 사용자를 선택하세요.');
 const u=USERS.find(x=>String(x[F.ukey])===String(sel));if(!u)return;
 if(!confirm(u[F.uname]+' 사용자를 삭제할까요?\\n메뉴 권한도 함께 삭제됩니다.'))return;
 if(window.MESDB&&MESDB.online){try{await MESDB.rest('${R.perms.name}?'+F.pkey+'=eq.'+encodeURIComponent(sel),{method:'DELETE',headers:{Prefer:'return=minimal'}})}catch(e){}}
 for(let i=PERMS.length-1;i>=0;i--)if(String(PERMS[i][F.pkey])===String(sel))PERMS.splice(i,1);
 const i=USERS.indexOf(u);if(i>=0)USERS.splice(i,1);
 if(window.MESDB&&MESDB.syncMaster)MESDB.syncMaster().catch(()=>{});
 sel='';loadedFor=null;renderUsers();renderPerms(true);msg(u[F.uname]+' 삭제했습니다.')}
function refresh(){if(window.MESDB&&MESDB.reloadMaster)MESDB.reloadMaster();renderUsers();if(sel)pick(sel);msg('다시 조회했습니다.')}
window.MES={search:renderUsers,save:saveUser,delete:delUser,setMessage:msg};
<\/script>
<script src="mes_db.js"><\/script>
<script>
MESDB.master({page:'${slug(s.name)}:users',table:'${R.users.name}',pk:'${f.ukey}',map:${mapOf(R.users)},get:()=>USERS,render:()=>{renderUsers();if(sel)pick(sel);else if(USERS.length)pick(USERS[0][F.ukey])}});
MESDB.table('${R.perms.name}').select('select=*').then(rs=>{PERMS.length=0;PERMS.push(...rs);loadedFor=null;renderPerms(true)}).catch(()=>{});
boot();
<\/script>
<div id="toast"></div></body></html>
`;
}
/* ═══ 파이프라인 보드 화면 ═══
   외주가공 발주형: [제번 목록] · [부품 × 공정1..N 매트릭스] · [협력업체] · [구매요청 리스트]
   연결 테이블 역할은 이름·컬럼으로 추정: 제번(job), 부품(steps 컬럼), 라인(status+step_no), 업체(vendor). */
function boardRoles(ts){
 const has=(t,re)=>colsOf(t).some(c=>re.test(c.name));
 const nm=(t,re)=>re.test(t.name);
 const pick=(re1,re2)=>ts.find(t=>re1&&nm(t,re1))||ts.find(t=>re2&&has(t,re2));
 const vendors=pick(/vendor|supplier|partner/i,/^vendor_name$|^supplier_name$/i);
 const lines=ts.find(t=>t!==vendors&&has(t,/^status$/i)&&has(t,/step_no|category/i))||ts.find(t=>t!==vendors&&nm(t,/line|order/i));
 const routes=ts.find(t=>t!==vendors&&t!==lines&&(nm(t,/standard_route|standard_process|route/i)||(has(t,/^steps$/i)&&!has(t,/^job_no$/i))));
 const parts=ts.find(t=>t!==vendors&&t!==lines&&t!==routes&&has(t,/^steps$/i))||ts.find(t=>t!==vendors&&t!==lines&&t!==routes&&nm(t,/part/i));
 const jobs=ts.find(t=>t!==vendors&&t!==lines&&t!==parts&&t!==routes&&has(t,/^job_no$|^order_no$/i))||ts.find(t=>![vendors,lines,parts,routes].includes(t))||parts;
 const col=(t,re,d)=>{const c=t&&colsOf(t).find(x=>re.test(x.name));return c?c.name:d};
 const f={
  job:col(jobs,/^job_no$|^order_no$|_no$/i,'job_no'),item:col(jobs,/item_name|product|name$/i,null),
  pjob:col(parts,/^job_no$|^order_no$/i,'job_no'),part:col(parts,/^part_no$|^part_code$|part/i,'part_no'),pname:col(parts,/part_name|name$/i,null),pqty:col(parts,/^qty$|quantity/i,null),steps:col(parts,/^steps$/i,'steps'),
  ljob:col(lines,/^job_no$/i,'job_no'),lpart:col(lines,/^part_no$/i,'part_no'),lstep:col(lines,/^step_no$/i,'step_no'),lmp:col(lines,/^machining_process_code$/i,null)||col(lines,/process_code/i,'machining_process_code'),lstatus:col(lines,/^status$/i,'status'),lvendor:col(lines,/vendor_name|vendor/i,'vendor_name'),lqty:col(lines,/order_qty|^qty$/i,'order_qty'),lrdate:col(lines,/required_date|due/i,'required_date'),lcat:col(lines,/^category$/i,null),
  lid:col(lines,/^line_id$|^id$/i,'line_id'),lrqty:col(lines,/receipt_qty|recv_qty/i,null),lrcv:col(lines,/receipt_date|recv_date/i,null),lprice:col(lines,/^unit_price$/i,null),lquote:col(lines,/quote_price/i,null),lconfirm:col(lines,/confirm_price|confirm_amount/i,null),lcdate:col(lines,/confirm_date/i,null),
  vname:col(vendors,/vendor_name|supplier_name|name$/i,'vendor_name'),
  rno:col(routes,/standard_process_no|route_no|^row_no$/i,'row_no'),rname:col(routes,/standard_process_name|route_name|name$/i,'standard_process_name'),rsteps:col(routes,/^steps$/i,'steps'),pstd:col(parts,/standard_process|route/i,null)};
 return{jobs,parts,lines,vendors,routes,f};
}
function boardScreen(s,ts,loc){
 const R=boardRoles(ts);if(!R.jobs)return blankScreen(s,loc);
 const f=R.f;const NSTEP=7;
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css">
<style>
.body{display:flex;flex-direction:column;gap:6px}
.bar{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.bar .lab{min-width:40px}.bar .field{width:160px}
.panes{display:grid;grid-template-columns:minmax(220px,1fr) minmax(420px,2.6fr) 130px;gap:6px;min-height:0;flex:1 1 46%}
.midbar{display:flex;gap:6px;align-items:center;justify-content:flex-end}
.req{flex:1 1 34%;min-height:120px}
.hint{color:#5b6b7a;font-size:11.5px;border:1px solid #c8d3dc;background:#f3f7fa;padding:3px 8px;border-radius:3px}
.legend{margin-left:10px;font-weight:400;color:#5b6b7a;font-size:11px}.legend i{display:inline-block;width:10px;height:10px;margin:0 3px 0 8px;vertical-align:-1px;border-radius:2px}
td.st{text-align:center;cursor:pointer;font-size:11px;white-space:nowrap}
td.st.next{background:#8fdc6b;font-weight:700}td.st.req{background:#8e6bb0;color:#fff}td.st.out{background:#e07a1f;color:#fff}td.st.in{background:#2f6fb5;color:#fff}td.st.done{background:#8b98a3;color:#fff}
td.st.pick{outline:2px solid #f2a93b;outline-offset:-2px}
tr.von td{background:var(--sel);color:#fff}
@media(max-width:1100px){.panes{grid-template-columns:1fr;flex:none}.panes .panel{min-height:160px;max-height:260px}.req{flex:none;max-height:240px}}
</style></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small></div>
  <div class="body">
    <div class="bar"><div class="lab">제번</div><input id="qJob" class="field" placeholder="제번 입력/선택" list="dlJob"><datalist id="dlJob"></datalist>
      <div class="lab">품명</div><input id="qItem" class="field" placeholder="품명 입력/선택">
      <div class="lab">업체</div><input id="qVen" class="field" placeholder="" readonly title="오른쪽 협력업체에서 선택">
      <button class="btn" onclick="renderJobs()">⌕ 조회</button><button class="btn" onclick="init()">⟳ 새로고침</button>
      <span class="hint">※ 공정 칸 <b>더블클릭</b> → 입고 · 입고확정(금액) · 발주취소 선택 &nbsp;|&nbsp; 공정은 <b>가공공정표준</b>에서 선택</span></div>
    <section class="panes">
      <div class="panel"><div class="cap">제번리스트</div><div class="tablewrap"><table><thead><tr><th>제번</th><th>품명</th><th class="c">부품</th><th class="c">진행</th></tr></thead><tbody id="jobBody"></tbody></table></div></div>
      <div class="panel"><div class="cap">부품별 가공공정 리스트<span class="legend"><i style="background:#8fdc6b"></i>다음 공정(클릭)<i style="background:#8e6bb0"></i>요청<i style="background:#e07a1f"></i>출고<i style="background:#2f6fb5"></i>입고<i style="background:#8b98a3"></i>완료<i style="background:#fff7e0;border:1px solid #e0c97a"></i>공정 미지정(표준 선택)</span></div>
        <div class="tablewrap"><table style="min-width:820px"><thead><tr><th style="width:36px">조</th><th style="width:90px">부품코드</th><th>부품명</th><th class="r" style="width:50px">수량</th>${Array.from({length:NSTEP},(_,i)=>`<th class="c" style="width:78px">공정${i+1}</th>`).join('')}</tr></thead><tbody id="routeBody"></tbody></table></div></div>
      <div class="panel"><div class="cap">협력업체</div><div style="padding:4px"><input id="venQ" class="field" style="width:100%" placeholder="업체 검색" oninput="renderVen()"></div><div class="tablewrap"><table><tbody id="venBody"></tbody></table></div></div>
    </section>
    <div class="midbar"><span class="lab">입고요구일</span><input id="rdate" class="field" type="date" style="width:140px"><button class="btn primary" onclick="addReq()">⬇ 요청추가</button><button class="btn warn" onclick="delReq()">⬆ 요청삭제</button><button class="btn" onclick="submitReq()">▤ 발주등록</button></div>
    <section class="panel req"><div class="cap">구매요청 리스트 <span class="right" id="reqCnt"></span></div>
      <div class="tablewrap"><table><thead><tr><th style="width:36px">No</th><th style="width:36px" class="c">선택</th><th>협력업체</th><th>제번</th><th>품명</th><th>품번</th><th>부품명</th><th class="c">순번</th><th>가공공정</th><th class="r">수량</th><th>입고요구일</th><th>작성자</th></tr></thead><tbody id="reqBody"></tbody></table></div></section>
  </div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">제번을 고르고, 녹색(다음 공정) 칸을 클릭한 뒤 업체를 선택해 요청을 추가하세요.</span></footer>
</div>
<div class="modal-bg" id="actBg" onclick="if(event.target===this)closeAct()"><div class="modal" style="min-width:360px;max-width:460px">
  <div class="t"><span id="actTitle">공정 처리</span><span class="x" onclick="closeAct()">×</span></div>
  <div class="bd" id="actBody"></div>
  <div class="bt" id="actBt"></div>
</div></div>
<style>
.modal-bg{position:fixed;inset:0;background:rgba(20,28,35,.38);display:none;align-items:center;justify-content:center;z-index:1000}.modal-bg.on{display:flex}
.modal{background:#fff;border:1px solid #7f8f9c;box-shadow:0 6px 24px rgba(0,0,0,.3);display:flex;flex-direction:column}
.modal .t{height:30px;display:flex;align-items:center;padding:0 12px;color:#fff;background:linear-gradient(#5f7f9f,#3f5f7d);font-weight:700}.modal .t .x{margin-left:auto;cursor:pointer;font-size:16px}
.modal .bd{padding:12px}.modal .bt{padding:8px 12px;display:flex;justify-content:flex-end;gap:5px;background:#f7f9fa;border-top:1px solid #e3e9ed;flex-wrap:wrap}
.act-info{background:#f4f7f9;border:1px solid #dde3e8;padding:7px 10px;margin-bottom:8px;line-height:1.7}
.act-grid{display:grid;grid-template-columns:90px 1fr;gap:4px 6px;align-items:center}
.act-grid .lab{min-height:25px}
.btn.in{background:linear-gradient(#e8f1fb,#c9dcf2);color:#1e4f86;border-color:#7fa6c9}.btn.ok{background:linear-gradient(#e9f6ee,#c8e7d2);color:#1d5a34;border-color:#7fb894}
td.st.noroute{background:#fff7e0;color:#8a6d00;font-size:11px}
.rsel{height:24px;font-size:11.5px;max-width:170px}
</style>
<script>
const JOBS=[],PARTS=[],VENDORS=[],LINES=[],REQ=[],ROUTES=[];window.JOBS=JOBS;window.PARTS=PARTS;window.VENDORS=VENDORS;window.LINES=LINES;window.ROUTES=ROUTES;
const F=${JSON.stringify(f)};const NSTEP=${NSTEP};
const PROC={MC:'머시닝',GR:'연마',HT:'열처리',WE:'와이어',LA:'레이저',PL:'도금',ED:'방전',DR:'드릴'};
const D2S={'발주':'out','입고':'in','입고확정':'done'},S2K={out:'출고',in:'입고',done:'완료',req:'요청',next:'다음'};
let curJob=null,curVen='',PICK=new Set();
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const today=()=>{const d=new Date(),z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,10)};function msg(t){message.textContent=t}
const stepCode=x=>String((x&&typeof x==='object')?(x.process_code||x.code||''):x||'');
const stepsOf=p=>{let v=p[F.steps];if(typeof v==='string'){try{v=JSON.parse(v)}catch(e){v=v.split(/[,>→]/).map(x=>x.trim()).filter(Boolean)}}return Array.isArray(v)?v.map(stepCode):[]};
const lineOf=(job,part,i)=>LINES.find(l=>l[F.ljob]===job&&l[F.lpart]===part&&Number(l[F.lstep])===i+1);
const reqOf=(job,part,i)=>REQ.find(r=>r.job===job&&r.part===part&&r.sn===i+1);
function init(){$('rdate').value=$('rdate').value||new Date(Date.now()+12*864e5).toISOString().slice(0,10);dlJob.innerHTML=JOBS.map(j=>'<option value="'+esc(j[F.job])+'">').join('');renderJobs();renderVen();renderReq();if(curJob)renderRoutes()}
function partsOf(job){return PARTS.filter(p=>p[F.pjob]===job)}
function progress(job){const ps=partsOf(job);let tot=0,done=0;for(const p of ps){const st=stepsOf(p);tot+=st.length;st.forEach((_,i)=>{const l=lineOf(job,p[F.part],i);if(l&&l[F.lstatus]==='입고확정')done++})}return tot?done+'/'+tot:'-'}
function renderJobs(){const qj=($('qJob').value||'').toLowerCase(),qi=($('qItem').value||'').toLowerCase();
 const v=JOBS.filter(j=>(!qj||String(j[F.job]).toLowerCase().includes(qj))&&(!qi||!F.item||String(j[F.item]||'').toLowerCase().includes(qi)));
 jobBody.innerHTML=v.length?v.map(j=>'<tr class="'+(curJob===j[F.job]?'sel':'')+'" onclick="pickJob(JOBS.find(x=>x[F.job]===\\''+esc(j[F.job])+'\\'))"><td>'+esc(j[F.job])+'</td><td>'+esc(F.item?j[F.item]:'')+'</td><td class="c">'+partsOf(j[F.job]).length+'</td><td class="c">'+progress(j[F.job])+'</td></tr>').join(''):'<tr><td colspan="4" class="empty">제번이 없습니다.</td></tr>'}
function pickJob(j){if(!j)return;curJob=j[F.job];PICK.clear();renderJobs();renderRoutes();msg(curJob+' — 부품 '+partsOf(curJob).length+'개')}
function cellState(job,part,st,i){const l=lineOf(job,part,i);if(l)return D2S[l[F.lstatus]]||'out';if(reqOf(job,part,i))return 'req';
 const prev=i===0?null:lineOf(job,part,i-1);if(i===0||(prev&&(prev[F.lstatus]==='입고'||prev[F.lstatus]==='입고확정')))return 'next';return ''}
function renderRoutes(){const ps=curJob?partsOf(curJob):[];
 routeBody.innerHTML=ps.length?ps.map((p,pi)=>{const st=stepsOf(p);const ordered=LINES.some(l=>l[F.ljob]===curJob&&l[F.lpart]===p[F.part]);
  const rsel='<select class="rsel" onchange="applyRoute(\\''+esc(p[F.part])+'\\',this.value)"><option value="">가공공정표준 선택…</option>'+ROUTES.map(r=>'<option value="'+esc(r[F.rno])+'"'+(F.pstd&&p[F.pstd]===r[F.rname]?' selected':'')+'>'+esc(r[F.rname])+' ('+stepsOfRoute(r).map(c=>PROC[c]||c).join('→')+')</option>').join('')+'</select>';
  let h='<tr><td class="c">'+(pi+1)+'</td><td>'+esc(p[F.part])+(!ordered&&st.length?'<br><small style="color:#8a94a6;cursor:pointer" onclick="changeRoute(\\''+esc(p[F.part])+'\\')" title="발주 전이라 표준을 바꿀 수 있습니다">≡ 표준변경</small>':'')+'</td><td>'+esc(F.pname?p[F.pname]:'')+'</td><td class="r">'+esc(F.pqty?p[F.pqty]:'')+'</td>';
  if(!st.length){return h+'<td class="st noroute" colspan="'+NSTEP+'" style="text-align:left;padding:4px 8px">공정 미지정 — '+rsel+'</td></tr>'}
  for(let i=0;i<NSTEP;i++){const c=st[i];if(!c){h+='<td></td>';continue}const s=cellState(curJob,p[F.part],c,i);const k=curJob+'|'+p[F.part]+'|'+i;const l=lineOf(curJob,p[F.part],i);
   h+='<td class="st '+s+(PICK.has(k)?' pick':'')+'" title="'+esc((PROC[c]||c)+(l?' · '+l[F.lvendor]+' · '+l[F.lstatus]:''))+'" onclick="tap(\\''+esc(k)+'\\',\\''+s+'\\')" ondblclick="act(\\''+esc(k)+'\\')">'+esc(PROC[c]||c)+(l?'<br><small>'+esc(l[F.lvendor]||'')+'</small>':s==='req'?'<br><small>요청</small>':'')+'</td>'}
  return h+'</tr>'}).join(''):'<tr><td colspan="'+(4+NSTEP)+'" class="empty">왼쪽에서 제번을 선택하세요.</td></tr>'}
function tap(k,s){if(s!=='next')return;PICK.has(k)?PICK.delete(k):PICK.add(k);renderRoutes();msg('선택 '+PICK.size+'건 — 오른쪽에서 업체를 고르고 [요청추가]')}
function renderVen(){const q=($('venQ').value||'').toLowerCase();venBody.innerHTML=VENDORS.filter(v=>!q||String(v[F.vname]).toLowerCase().includes(q)).map(v=>'<tr class="'+(curVen===v[F.vname]?'von':'')+'" onclick="pickVen(\\''+esc(v[F.vname])+'\\')"><td>'+esc(v[F.vname])+'</td></tr>').join('')}
function pickVen(n){curVen=n;$('qVen').value=n;renderVen();msg('업체: '+n)}
function addReq(){if(!PICK.size)return msg('녹색(다음 공정) 칸을 먼저 클릭하세요.');if(!curVen)return msg('협력업체를 선택하세요.');
 let n=0;for(const k of PICK){const [job,part,i]=k.split('|');const p=partsOf(job).find(x=>x[F.part]===part);const c=stepsOf(p)[+i];if(reqOf(job,part,+i))continue;
  REQ.push({sel:false,vendor:curVen,job,item:F.item?(JOBS.find(j=>j[F.job]===job)||{})[F.item]:'',part,partName:F.pname?p[F.pname]:'',sn:+i+1,mp:c,mpName:PROC[c]||c,qty:F.pqty?(p[F.pqty]||1):1,rdate:$('rdate').value,writer:'담당자'});n++}
 PICK.clear();renderRoutes();renderReq();msg('요청 '+n+'건 추가 — [발주등록] 으로 확정하세요.')}
function delReq(){const b=REQ.length;for(let i=REQ.length-1;i>=0;i--)if(REQ[i].sel)REQ.splice(i,1);if(REQ.length===b)return msg('삭제할 요청을 체크하세요.');renderReq();renderRoutes();msg('요청 '+(b-REQ.length)+'건 삭제')}
function renderReq(){reqBody.innerHTML=REQ.length?REQ.map((r,i)=>'<tr><td>'+(i+1)+'</td><td class="c"><input type="checkbox" '+(r.sel?'checked':'')+' onchange="REQ['+i+'].sel=this.checked"></td><td>'+esc(r.vendor)+'</td><td>'+esc(r.job)+'</td><td>'+esc(r.item)+'</td><td>'+esc(r.part)+'</td><td>'+esc(r.partName)+'</td><td class="c">'+r.sn+'</td><td>'+esc(r.mpName)+'</td><td class="r">'+r.qty+'</td><td>'+esc(r.rdate)+'</td><td>'+esc(r.writer)+'</td></tr>').join(''):'<tr><td colspan="12" class="empty">요청이 없습니다.</td></tr>';reqCnt.textContent=REQ.length+'건'}
async function submitReq(){if(!REQ.length)return msg('등록할 요청이 없습니다.');
 const rows=REQ.map(r=>({${f.lcat?`[F.lcat]:'외주가공',`:''}[F.lstatus]:'발주',[F.lvendor]:r.vendor,[F.ljob]:r.job,[F.lpart]:r.part,[F.lstep]:r.sn,[F.lmp]:r.mp,[F.lqty]:r.qty,[F.lrdate]:r.rdate||null}));
 if(window.MESDB&&MESDB.online&&MESDB.newLines){try{await MESDB.newLines(rows)}catch(e){return msg('DB 등록 실패: '+e.message.slice(0,100))}}
 LINES.push(...rows);const n=REQ.length;REQ.length=0;renderReq();renderRoutes();renderJobs();msg('외주가공 발주 '+n+'건 등록 (공정 리스트에 출고 표시)')}
const stepsOfRoute=r=>{let v=r[F.rsteps];if(typeof v==='string'){try{v=JSON.parse(v)}catch(e){v=v.split(/[,>→]/).map(x=>x.trim()).filter(Boolean)}}return Array.isArray(v)?v.map(stepCode):[]};
async function applyRoute(part,rno){const r=ROUTES.find(x=>String(x[F.rno])===String(rno));const p=partsOf(curJob).find(x=>x[F.part]===part);if(!r||!p)return;
 p[F.steps]=stepsOfRoute(r);if(F.pstd)p[F.pstd]=r[F.rname];
 if(window.MESDB&&MESDB.online){try{await MESDB.table('${R.parts?R.parts.name:'machining_plan_parts'}').upsert(p)}catch(e){}}
 renderRoutes();renderJobs();msg(part+' 가공공정 = '+r[F.rname]+' ('+p[F.steps].length+'공정)')}
function changeRoute(part){const p=partsOf(curJob).find(x=>x[F.part]===part);if(!p)return;if(LINES.some(l=>l[F.ljob]===curJob&&l[F.lpart]===part))return msg('이미 발주된 부품은 표준을 바꿀 수 없습니다.');p[F.steps]=[];if(F.pstd)p[F.pstd]='';renderRoutes();msg(part+' — 가공공정표준을 다시 선택하세요.')}
/* ── 공정 셀 더블클릭 → 상태별 처리 선택창 ── */
let ACT=null;
function closeAct(){actBg.classList.remove('on');ACT=null}
const num=v=>{const n=Number(String(v??'').replace(/[^0-9.-]/g,''));return isNaN(n)?0:n};
function act(k){const [job,part,i0]=k.split('|');const i=+i0;const l=lineOf(job,part,i);
 if(!l)return msg('아직 발주되지 않은 공정입니다. 녹색 칸을 클릭해 요청을 추가하세요.');
 ACT={l,job,part,i};const cur=l[F.lstatus];const p=partsOf(job).find(x=>x[F.part]===part)||{};const c=stepsOf(p)[i];
 const info='<div class="act-info"><b>'+esc(part)+'</b> '+esc(F.pname?p[F.pname]||'':'')+' · '+(i+1)+'공정 <b>'+esc(PROC[c]||c)+'</b><br>업체 '+esc(l[F.lvendor]||'-')+' · 발주수량 '+esc(l[F.lqty]??'')+' · 현재 <b>'+esc(S2K[D2S[cur]]||cur)+'</b></div>';
 let body='',bt='';
 if(cur==='발주'){actTitle.textContent='출고(발주) 상태 — 처리 선택';
  body=info+'<div class="act-grid"><div class="lab">입고일</div><input id="a_rdate" class="field" type="date" value="'+today()+'">'+(F.lrqty?'<div class="lab">입고수량</div><input id="a_rqty" class="field" type="number" value="'+esc(l[F.lqty]??1)+'">':'')+'</div><div style="color:#8a94a6;font-size:11.5px;margin-top:8px">입고 처리하면 다음 공정을 발주할 수 있습니다. 금액은 입고확정 때 입력합니다.</div>';
  bt='<button class="btn in" onclick="doReceive()">⬇ 입고</button><button class="btn warn" onclick="doCancel()">✖ 발주취소</button><button class="btn" onclick="closeAct()">닫기</button>'}
 else if(cur==='입고'){actTitle.textContent='입고 상태 — 입고확정(금액) 또는 입고취소';
  const q=num(l[F.lrqty]??l[F.lqty]??1),up=num(F.lprice?l[F.lprice]:0),qt=num(F.lquote?l[F.lquote]:0);
  body=info+'<div class="act-grid"><div class="lab">확정일</div><input id="a_cdate" class="field" type="date" value="'+today()+'">'+(F.lrqty?'<div class="lab">입고수량</div><input id="a_rqty" class="field" type="number" value="'+q+'" oninput="calcAmt()">':'')+(F.lprice?'<div class="lab">단가</div><input id="a_price" class="field" type="number" value="'+up+'" oninput="calcAmt()">':'')+(F.lquote?'<div class="lab">견적금액</div><input class="field" value="'+qt.toLocaleString()+'" readonly>':'')+(F.lconfirm?'<div class="lab">확정금액</div><input id="a_amt" class="field" type="number" value="'+(num(l[F.lconfirm])||up*q)+'">':'')+'</div><div style="color:#8a94a6;font-size:11.5px;margin-top:8px">확정금액은 단가×입고수량으로 자동 계산되며 직접 고칠 수 있습니다. 확정 후 매입정산에 반영됩니다.</div>';
  bt='<button class="btn ok" onclick="doConfirm()">✔ 입고확정</button><button class="btn warn" onclick="doUnreceive()">↩ 입고취소</button><button class="btn" onclick="closeAct()">닫기</button>'}
 else{actTitle.textContent='완료(입고확정) 상태';
  body=info+'<div class="act-grid">'+(F.lconfirm?'<div class="lab">확정금액</div><input class="field" value="'+num(l[F.lconfirm]).toLocaleString()+'" readonly>':'')+(F.lcdate?'<div class="lab">확정일</div><input class="field" value="'+esc(l[F.lcdate]||'')+'" readonly>':'')+'</div><div style="color:#8a94a6;font-size:11.5px;margin-top:8px">확정을 취소하면 입고 상태로 돌아갑니다 (정산 반영분 확인 필요).</div>';
  bt='<button class="btn warn" onclick="doUnconfirm()">↩ 확정취소</button><button class="btn" onclick="closeAct()">닫기</button>'}
 actBody.innerHTML=body;actBt.innerHTML=bt;actBg.classList.add('on')}
function calcAmt(){const q=num(document.getElementById('a_rqty')?.value),p=num(document.getElementById('a_price')?.value);const a=document.getElementById('a_amt');if(a&&q&&p)a.value=q*p}
async function persist(l){if(window.MESDB&&MESDB.online){try{await MESDB.table('${R.lines?R.lines.name:'order_lines'}').upsert(l${f.lid?`,'${f.lid}'`:''})}catch(e){msg('DB 반영 실패: '+e.message.slice(0,100))}}}
function doReceive(){const l=ACT.l;l[F.lstatus]='입고';if(F.lrcv)l[F.lrcv]=document.getElementById('a_rdate').value;if(F.lrqty)l[F.lrqty]=num(document.getElementById('a_rqty')?.value)||l[F.lqty];persist(l);closeAct();renderRoutes();renderJobs();msg(l[F.lpart]+' '+(ACT_i()+1)+'공정 입고 — 다음 공정 발주 가능')}
function doConfirm(){const l=ACT.l;l[F.lstatus]='입고확정';if(F.lcdate)l[F.lcdate]=document.getElementById('a_cdate').value;if(F.lrqty)l[F.lrqty]=num(document.getElementById('a_rqty')?.value)||l[F.lqty];if(F.lprice)l[F.lprice]=num(document.getElementById('a_price')?.value);if(F.lconfirm)l[F.lconfirm]=num(document.getElementById('a_amt')?.value);persist(l);closeAct();renderRoutes();renderJobs();msg(l[F.lpart]+' 입고확정 — 확정금액 '+(F.lconfirm?num(l[F.lconfirm]).toLocaleString()+'원':''))}
function doUnreceive(){const l=ACT.l;if(!confirm('입고를 취소하고 출고(발주) 상태로 되돌릴까요?'))return;l[F.lstatus]='발주';if(F.lrcv)l[F.lrcv]=null;persist(l);closeAct();renderRoutes();renderJobs();msg(l[F.lpart]+' 입고취소')}
function doUnconfirm(){const l=ACT.l;if(!confirm('입고확정을 취소할까요?'))return;l[F.lstatus]='입고';if(F.lcdate)l[F.lcdate]=null;persist(l);closeAct();renderRoutes();renderJobs();msg(l[F.lpart]+' 확정취소')}
async function doCancel(){const l=ACT.l;const nx=lineOf(ACT.job,ACT.part,ACT.i+1);if(nx)return msg('다음 공정이 이미 발주되어 취소할 수 없습니다. 다음 공정부터 취소하세요.');
 if(!confirm(l[F.lpart]+' '+(ACT.i+1)+'공정 발주를 취소할까요? (라인 삭제)'))return;
 if(window.MESDB&&MESDB.online&&l[F.lid]!=null){try{if(MESDB.delLines)await MESDB.delLines([l[F.lid]]);else await MESDB.table('${R.lines?R.lines.name:'order_lines'}').delete({[F.lid]:l[F.lid]})}catch(e){return msg('DB 삭제 실패: '+e.message.slice(0,100))}}
 const k=LINES.indexOf(l);if(k>=0)LINES.splice(k,1);closeAct();renderRoutes();renderJobs();msg(l[F.lpart]+' 발주취소 — 다시 녹색 칸으로 돌아왔습니다.')}
const ACT_i=()=>ACT?ACT.i:0;
window.MES={search:renderJobs,setMessage:msg};
<\/script>
<script src="mes_db.js"><\/script>
<script>(async()=>{try{await MESDB.ready}catch(e){}if(!window.MESDB||!MESDB.online)return;
 try{JOBS.length=0;JOBS.push(...await MESDB.table('${R.jobs.name}').select('select=*'))}catch(e){}
 ${R.parts?`try{PARTS.length=0;PARTS.push(...await MESDB.table('${R.parts.name}').select('select=*'))}catch(e){}`:''}
 ${R.vendors?`try{VENDORS.length=0;VENDORS.push(...await MESDB.table('${R.vendors.name}').select('select=*'))}catch(e){}`:''}
 ${R.lines?`try{LINES.length=0;LINES.push(...await MESDB.table('${R.lines.name}').select('select=*${f.lcat?'&'+f.lcat+'=eq.외주가공':''}'))}catch(e){}`:''}
 ${R.routes?`try{ROUTES.length=0;ROUTES.push(...await MESDB.table('${R.routes.name}').select('select=*&order=${f.rno}'))}catch(e){}`:''}
 init()})();<\/script>
<div id="toast"></div></body></html>
`;
}
/* ═══ 체크시트 화면 ═══
   테이블의 chk_* 컬럼 = 점검항목. 헤더(점검일·점검자·대상)는 위에, 항목은 OK/NG/N.A 토글로 세로 나열.
   ng_count / result 는 자동 집계. 목록에는 헤더 + NG수 + 판정만 보인다. */
const isCheckTable=t=>!!t&&colsOf(t).filter(c=>/^chk_/i.test(c.name)).length>=2;
function checkScreen(s,t,loc){
 const cols=colsOf(t),pk=cols.find(c=>c.pk)||cols[0];
 const items=cols.filter(c=>/^chk_/i.test(c.name));
 const AUTO=new Set(['ng_count','result','created_at','updated_at']);
 const head=cols.filter(c=>!/^chk_/i.test(c.name)&&!AUTO.has(c.name));
 const ngCol=cols.find(c=>c.name==='ng_count'),resCol=cols.find(c=>c.name==='result');
 const field=c=>c.type==='bool'?`<div class="check"><input id="f_${c.name}" type="checkbox"></div>`
  :`<input id="f_${c.name}" class="field${c.req?' req':''}" ${c.type==='num'?'type="number"':c.type==='date'?'type="date"':''}>`;
 const listCols=[...head,...(ngCol?[ngCol]:[]),...(resCol?[resCol]:[])];
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css">
<style>
.body{grid-template-columns:minmax(0,1fr) minmax(0,1fr);grid-template-rows:auto minmax(0,1fr)}
.body .hdr{grid-column:1/-1}
.items{overflow:auto}
.item{display:grid;grid-template-columns:32px minmax(0,1fr) 168px;align-items:center;border-bottom:1px solid #e0e6eb;min-height:38px}
.item .no{text-align:center;color:#8a94a6;font-size:11px}
.item .nm{padding:4px 8px}
.item .tg{display:flex;gap:3px;padding:3px 6px}
.tg button{flex:1;height:28px;border:1px solid #b7c1ca;background:#fff;border-radius:4px;font-weight:700;color:#8a94a6}
.tg button.ok.on{background:#2e7d32;color:#fff;border-color:#2e7d32}
.tg button.ng.on{background:#c62828;color:#fff;border-color:#c62828}
.tg button.na.on{background:#78909c;color:#fff;border-color:#78909c}
.sum{display:flex;gap:12px;align-items:center;padding:6px 8px;border-top:1px solid var(--line);background:#f7f9fb;font-weight:700}
.sum .ng{color:#c62828}.sum .res{margin-left:auto;padding:2px 10px;border-radius:10px;color:#fff;background:#2e7d32}.sum .res.bad{background:#c62828}
@media(max-width:880px){.body{grid-template-columns:1fr;grid-template-rows:auto auto minmax(0,1fr)}.item{grid-template-columns:28px minmax(0,1fr) 140px}}
</style></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small></div>
  <div class="body">
    <section class="panel hdr"><div class="cap">${s.name} 점검 <span class="right" id="modeTxt">신규</span></div>
      <div class="formgrid" style="border-left:0;border-top:0">
${head.map(c=>`        <div class="lab">${c.label||c.name}</div>${field(c)}`).join('\n')}
      </div>
      <div class="actions"><button class="btn primary" onclick="save()">▤ 저장</button><button class="btn" onclick="setAll('OK')">✓ 전체 OK</button><button class="btn" onclick="clearForm()">✕ 신규</button><button class="btn warn" onclick="remove()">✖ 삭제</button><button class="btn" onclick="exportCsv()">▤ EXCEL</button></div>
    </section>
    <section class="panel"><div class="cap">점검항목 <span class="right">${items.length}개 · OK / NG / N.A</span></div>
      <div class="items" id="items">
${items.map((c,i)=>`        <div class="item" data-k="${c.name}"><div class="no">${i+1}</div><div class="nm">${c.label||c.name.replace(/^chk_/,'')}</div><div class="tg"><button class="ok" onclick="setV('${c.name}','OK')">OK</button><button class="ng" onclick="setV('${c.name}','NG')">NG</button><button class="na" onclick="setV('${c.name}','N/A')">N.A</button></div></div>`).join('\n')}
      </div>
      <div class="sum">NG <span class="ng" id="ngTxt">0</span> 건 <span style="color:#8a94a6;font-weight:400">/ 미점검 <span id="naTxt">${items.length}</span></span><span class="res" id="resTxt">OK</span></div>
    </section>
    <section class="panel"><div class="cap">${s.name} 목록 <span class="right"><input id="q" class="field" style="width:140px;height:22px" placeholder="검색" oninput="render()"> &nbsp;<span id="countText"></span></span></div>
      <div class="tablewrap"><table><thead><tr>${listCols.map(c=>`<th${c.type==='num'?' class="r"':''}>${c.label||c.name}</th>`).join('')}</tr></thead><tbody id="tbody"></tbody></table></div>
    </section>
  </div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">항목을 OK/NG 로 누르면 NG수와 판정이 자동 집계됩니다.</span></footer>
</div>
<script>
const rows=[];window.rows=rows;let sel=null;const V={};
const F=${JSON.stringify(cols.map(c=>c.name))},T=${JSON.stringify(Object.fromEntries(cols.map(c=>[c.name,c.type])))},PK='${pk.name}';
const HEAD=${JSON.stringify(head.map(c=>c.name))},ITEMS=${JSON.stringify(items.map(c=>c.name))},LIST=${JSON.stringify(listCols.map(c=>c.name))};
const REQ=${JSON.stringify(head.filter(c=>c.req&&!c.pk).map(c=>c.name))},NGC=${JSON.stringify(ngCol?ngCol.name:null)},RESC=${JSON.stringify(resCol?resCol.name:null)};
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmt=n=>(n===''||n==null)?'':Number(n).toLocaleString('ko-KR');const today=()=>{const d=new Date(),z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,10)};
const nowT=()=>new Date().toTimeString().slice(0,5);
function msg(t){message.textContent=t}
function paint(){for(const k of ITEMS){const el=document.querySelector('.item[data-k="'+k+'"]');if(!el)continue;
  el.querySelectorAll('.tg button').forEach(b=>b.classList.toggle('on',(b.classList.contains('ok')&&V[k]==='OK')||(b.classList.contains('ng')&&V[k]==='NG')||(b.classList.contains('na')&&V[k]==='N/A')))}
 const ng=ITEMS.filter(k=>V[k]==='NG').length,na=ITEMS.filter(k=>!V[k]).length;
 ngTxt.textContent=ng;naTxt.textContent=na;resTxt.textContent=ng?'NG':'OK';resTxt.classList.toggle('bad',!!ng)}
function setV(k,v){V[k]=(V[k]===v)?'':v;paint()}
function setAll(v){for(const k of ITEMS)V[k]=v;paint()}
function cell(r,f){const v=r[f];return T[f]==='num'?fmt(v):T[f]==='bool'?(v?'✓':''):esc(v)}
function render(){const q=($('q').value||'').trim().toLowerCase();
 const view=rows.filter(r=>!q||F.some(f=>String(r[f]??'').toLowerCase().includes(q))).sort((a,b)=>String(b[PK]).localeCompare(String(a[PK])));
 tbody.innerHTML=view.length?view.map(r=>'<tr class="'+(r[PK]===sel?'sel':'')+'" onclick="pick(\\''+esc(String(r[PK]))+'\\')">'+LIST.map(f=>'<td'+(T[f]==='num'?' class="r"':'')+(f===RESC&&r[f]==='NG'?' style="color:#c62828;font-weight:700"':'')+'>'+cell(r,f)+'</td>').join('')+'</tr>').join('')
  :'<tr><td colspan="'+LIST.length+'" class="empty">등록된 점검이 없습니다.</td></tr>';countText.textContent=view.length+'건'}
function pick(k){const r=rows.find(x=>String(x[PK])===k);if(!r)return;sel=r[PK];
 HEAD.forEach(f=>{const el=$('f_'+f);if(!el)return;if(T[f]==='bool')el.checked=!!r[f];else el.value=r[f]??''});
 for(const i of ITEMS)V[i]=r[i]||'';paint();modeTxt.textContent='수정: '+k;render();msg(k+' 점검을 불러왔습니다.')}
function clearForm(){sel=null;HEAD.forEach(f=>{const el=$('f_'+f);if(!el)return;if(T[f]==='bool')el.checked=false;else el.value=T[f]==='date'?today():(/time/.test(f)?nowT():'')});
 for(const i of ITEMS)V[i]='';paint();modeTxt.textContent='신규';render();msg('새 점검을 입력하세요.')}
function save(){
 for(const f of REQ){const el=$('f_'+f);if(el&&T[f]!=='bool'&&!String(el.value).trim())return msg((el.previousElementSibling?.textContent||f)+' 은(는) 필수입니다.')}
 const miss=ITEMS.filter(k=>!V[k]);if(miss.length&&!confirm('미점검 항목이 '+miss.length+'개 있습니다. 그대로 저장할까요?'))return;
 const o={};for(const f of HEAD){const el=$('f_'+f);if(!el)continue;o[f]=T[f]==='bool'?el.checked:T[f]==='num'?(el.value===''?'':Number(el.value)):el.value}
 for(const i of ITEMS)o[i]=V[i]||'';
 const ng=ITEMS.filter(k=>V[k]==='NG').length;if(NGC)o[NGC]=ng;if(RESC)o[RESC]=ng?'NG':'OK';
 let no=o[PK];if(no===''||no==null){no=T[PK]==='num'?(rows.reduce((m,r)=>Math.max(m,Number(r[PK])||0),0)+1):'CK-'+today().slice(2).replaceAll('-','')+'-'+String(rows.length+1).padStart(3,'0')}
 o[PK]=no;if(sel!=null&&sel!==no){const i=rows.findIndex(r=>r[PK]===sel);if(i>=0)rows.splice(i,1)}
 const i=rows.findIndex(r=>r[PK]===no);if(i>=0)rows[i]=o;else rows.push(o);sel=no;const pe=$('f_'+PK);if(pe)pe.value=no;modeTxt.textContent='수정: '+no;render();
 msg(no+' 저장했습니다. (NG '+ng+'건 · '+(ng?'NG':'OK')+')')}
function remove(){if(sel==null)return msg('삭제할 점검을 목록에서 선택하세요.');if(!confirm(sel+' 을(를) 삭제할까요?'))return;const i=rows.findIndex(r=>r[PK]===sel);if(i>=0)rows.splice(i,1);const k=sel;clearForm();msg(k+' 삭제했습니다.')}
function exportCsv(){const h=${JSON.stringify(cols.map(c=>c.label||c.name))};const csv='\\ufeff'+[h,...rows.map(r=>F.map(f=>r[f]))].map(a=>a.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='${slug(s.name)}.csv';a.click()}
window.MES={search:render,save,setMessage:msg};clearForm();
<\/script>
<script src="mes_db.js"><\/script>
<script>MESDB.master({page:'${slug(s.name)}:rows',table:'${t.name}',pk:'${pk.name}',map:${mapOf(t)},get:()=>rows,render:()=>{render();if(sel!=null&&!rows.some(r=>r[PK]===sel))clearForm()}});<\/script>
<div id="toast"></div></body></html>
`;
}
function inputScreen(s,t,loc,lookups){
 const cols=colsOf(t),pk=cols.find(c=>c.pk)||cols[0],auto=autoNoConfig(t),al=alertConfig(t);
 const field=c=>c.formula?`<input id="f_${c.name}" class="field" readonly data-calc="1" title="계산식: ${esc(c.formula)}" style="background:#f3f7fb;color:#2f6fb5;font-weight:600">`:c.type==='bool'?`<div class="check"><input id="f_${c.name}" type="checkbox"></div>`:`<input id="f_${c.name}" class="field${c.req?' req':''}" ${c.type==='num'?'type="number"':c.type==='date'?'type="date"':''}${lookups.length&&/name$/.test(c.name)?` list="dl_${c.name}" autocomplete="off"`:''}>`;
 const dls=cols.filter(c=>!c.formula&&lookups.length&&/name$/.test(c.name)).map(c=>`<datalist id="dl_${c.name}"></datalist>`).join('');
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css"><style>.body{grid-template-rows:auto minmax(0,1fr)}input[data-calc]{border-color:#b9cce2}.duealert{display:none;padding:6px 9px;border:1px solid #f0c36d;background:#fff8e8;color:#8a5a00;font-weight:600}.duealert.on{display:block}.duealert.over{border-color:#e5a09a;background:#fff0ee;color:#a3261d}</style></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small></div>
  <div class="body">
    <section class="panel"><div class="cap">${s.name} 입력 <span class="right" id="modeTxt">신규</span></div>
      ${al.enabled&&al.dateCol?'<div id="dueAlert" class="duealert"></div>':''}<div class="formgrid" style="border-left:0;border-top:0">
${cols.map(c=>`        <div class="lab">${c.label||c.name}${c.formula?' <span title="자동 계산" style="color:#2f6fb5">ƒx</span>':''}</div>${field(c)}`).join('\n')}
      </div>${dls}
      <div class="actions"><button class="btn primary" onclick="save()">▤ 저장</button><button class="btn" onclick="clearForm()">✕ 신규</button><button class="btn warn" onclick="remove()">✖ 삭제</button><button class="btn" onclick="exportCsv()">▤ EXCEL</button></div>
    </section>
    <section class="panel"><div class="cap">${s.name} 목록 <span class="right"><input id="q" class="field" style="width:160px;height:22px" placeholder="검색" oninput="render()"> &nbsp;<span id="countText"></span></span></div>
      <div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th${c.type==='num'?' class="r"':''}>${c.label||c.name}${c.unit?` (${c.unit})`:''}</th>`).join('')}</tr></thead><tbody id="tbody"></tbody></table></div>
    </section>
  </div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">${auto.enabled?(pk.label||pk.name)+'를 비우면 '+autoNoPreview(t)+' 형식으로 자동 채번됩니다.':(pk.label||pk.name)+'는 직접 입력합니다.'}${cols.some(c=>c.formula)?' · ƒx 자동 계산':''}${al.enabled&&al.dateCol?' · 기한 '+al.days+'일 전 알림':''}</span></footer>
</div>
<script>
const rows=[];window.rows=rows;let sel=null;
const CM=${JSON.stringify(cols)},CMAP=Object.fromEntries(CM.map(c=>[c.name,c])),F=CM.map(c=>c.name),CALC=CM.filter(c=>c.formula).map(c=>c.name),T=Object.fromEntries(CM.map(c=>[c.name,c.type])),PK='${pk.name}',REQ=CM.filter(c=>c.req&&!c.pk&&!c.formula).map(c=>c.name),AUTO=${JSON.stringify(auto)},ALERT=${JSON.stringify(al)};
${calcRuntimeJs()}
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmt=n=>(n===''||n==null)?'':Number(n).toLocaleString('ko-KR');const today=()=>{const d=new Date(),z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,10)};
function msg(t){message.textContent=t}
function cell(r,f){calcApplyRow(r,CM);const c=CMAP[f],v=r[f];return c.formula?esc(calcFormat(v,c,true)):T[f]==='num'?fmt(v):T[f]==='bool'?(v?'✓':''):esc(v)}
function readForm(base){const o={...(base||{})};for(const f of F){const c=CMAP[f];if(c.formula)continue;const el=$('f_'+f);if(!el)continue;o[f]=T[f]==='bool'?el.checked:T[f]==='num'?(el.value===''?'':Number(el.value)):el.value}return calcApplyRow(o,CM)}
function dueState(o){if(!ALERT.enabled||!ALERT.dateCol||!o?.[ALERT.dateCol])return null;const a=new Date(today()),b=new Date(o[ALERT.dateCol]);if(!Number.isFinite(+b))return null;const d=Math.ceil((b-a)/864e5);return{days:d,kind:d<0?'over':d<=ALERT.days?'soon':'ok'}}
function renderDue(o){const el=$('dueAlert');if(!el)return;const z=dueState(o);el.className='duealert'+(z&&z.kind!=='ok'?' on'+(z.kind==='over'?' over':''):'');if(z&&z.kind==='over')el.textContent='⛔ 기한 '+Math.abs(z.days)+'일 초과';else if(z&&z.kind==='soon')el.textContent='⏰ 기한까지 '+z.days+'일 남았습니다.';else el.textContent=''}
function syncCalc(o){o=o?calcApplyRow(o,CM):readForm();for(const f of CALC){const el=$('f_'+f);if(el)el.value=calcFormat(o[f],CMAP[f],true)}renderDue(o);return o}
function render(){rows.forEach(r=>calcApplyRow(r,CM));const q=($('q').value||'').trim().toLowerCase();
 const view=rows.filter(r=>!q||F.some(f=>String(r[f]??'').toLowerCase().includes(q))).sort((a,b)=>String(b[PK]).localeCompare(String(a[PK])));
 tbody.innerHTML=view.length?view.map(r=>'<tr class="'+(r[PK]===sel?'sel':'')+'" onclick="pick(\\''+esc(String(r[PK]))+'\\')">'+F.map(f=>'<td'+(T[f]==='num'?' class="r"':'')+'>'+cell(r,f)+'</td>').join('')+'</tr>').join('')
  :'<tr><td colspan="'+F.length+'" class="empty">등록된 자료가 없습니다.</td></tr>';countText.textContent=view.length+'건'}
function pick(k){const r=rows.find(x=>String(x[PK])===k);if(!r)return;calcApplyRow(r,CM);sel=r[PK];F.forEach(f=>{const el=$('f_'+f);if(!el)return;const c=CMAP[f];if(c.formula)el.value=calcFormat(r[f],c,true);else if(T[f]==='bool')el.checked=!!r[f];else el.value=r[f]??''});modeTxt.textContent='수정: '+k;render();msg(k+' 을(를) 불러왔습니다.')}
function clearForm(){sel=null;F.forEach(f=>{const el=$('f_'+f),c=CMAP[f];if(!el||c.formula)return;if(T[f]==='bool')el.checked=false;else el.value=T[f]==='date'&&!/due|deadline|approved|reviewed|closed|completed|next_|updated_at/i.test(f)?today():''});syncCalc();modeTxt.textContent='신규';render();msg('새 자료를 입력하세요.');$('f_'+PK)?.focus()}
function autoDate(){const z=today().replaceAll('-','');return AUTO.date==='YYYYMMDD'?z:AUTO.date==='YYMMDD'?z.slice(2):AUTO.date==='YYMM'?z.slice(2,6):AUTO.date==='YYYY'?z.slice(0,4):''}
function nextNo(){if(!AUTO.enabled)return '';const base=[AUTO.prefix,autoDate()].filter(Boolean).join(AUTO.sep),p=base?base+AUTO.sep:'';const n=rows.filter(r=>String(r[PK]).startsWith(p)).map(r=>Number(String(r[PK]).slice(p.length))||0);return p+String((n.length?Math.max(...n):0)+1).padStart(AUTO.digits,'0')}
function save(){
 for(const f of REQ){const el=$('f_'+f);if(el&&T[f]!=='bool'&&!String(el.value).trim())return msg((el.previousElementSibling?.textContent||f)+' 은(는) 필수입니다.')}
 let no=String($('f_'+PK).value||'').trim();if(!no){if(AUTO.enabled)no=nextNo();else return msg((CMAP[PK]?.label||PK)+' 을(를) 입력하세요.')}const o=readForm();o[PK]=no;calcApplyRow(o,CM);
 if(sel&&sel!==no){const i=rows.findIndex(r=>r[PK]===sel);if(i>=0)rows.splice(i,1)}
 const i=rows.findIndex(r=>r[PK]===no);if(i>=0)rows[i]=o;else rows.push(o);sel=no;$('f_'+PK).value=no;syncCalc(o);modeTxt.textContent='수정: '+no;render();msg(no+' 저장했습니다.')}
function remove(){if(!sel)return msg('삭제할 행을 목록에서 선택하세요.');if(!confirm(sel+' 을(를) 삭제할까요?'))return;const i=rows.findIndex(r=>r[PK]===sel);if(i>=0)rows.splice(i,1);const k=sel;clearForm();msg(k+' 삭제했습니다.')}
function exportCsv(){rows.forEach(r=>calcApplyRow(r,CM));const h=${JSON.stringify(cols.map(c=>c.label||c.name))};const csv='\\ufeff'+[h,...rows.map(r=>F.map(f=>r[f]))].map(a=>a.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='${slug(s.name)}.csv';a.click()}
async function loadMasters(){if(!window.MESDB)return;try{await MESDB.ready}catch(e){}if(!MESDB.online)return;
${cols.filter(c=>!c.formula&&lookups.length&&/name$/.test(c.name)).map(c=>{const lk=lookups.find(l=>colsOf(l).some(x=>x.name===c.name))||lookups[0];const lc=colsOf(lk).find(x=>x.name===c.name)||colsOf(lk).find(x=>/name$/.test(x.name))||colsOf(lk)[0];return ` try{const rs=await MESDB.table('${lk.name}').select('select=${lc.name}&order=${lc.name}');$('dl_${c.name}').innerHTML=rs.map(r=>'<option value="'+esc(r['${lc.name}'])+'">').join('')}catch(e){}`}).join('\n')}
}
F.filter(f=>!CMAP[f].formula).forEach(f=>{const el=$('f_'+f);if(el)el.addEventListener(T[f]==='bool'?'change':'input',()=>syncCalc())});
window.MES={search:render,save,setMessage:msg};clearForm();
<\/script>
<script src="mes_db.js"><\/script>
<script>MESDB.master({page:'${slug(s.name)}:rows',table:'${t.name}',pk:'${pk.name}',map:${mapOf(t)},get:()=>rows,render:()=>{rows.forEach(r=>calcApplyRow(r,CM));render();if(sel&&!rows.some(r=>r[PK]===sel))clearForm()}});loadMasters();<\/script>
<div id="toast"></div></body></html>
`;
}
function statusScreen(s,t,loc){
 const cols=colsOf(t),pk=cols.find(c=>c.pk)||cols[0],dateCol=cols.find(c=>c.type==='date'&&!c.formula),textCols=cols.filter(c=>c.type==='text'&&!c.pk&&!c.formula).slice(0,3),numCols=cols.filter(c=>c.type==='num'),al=alertConfig(t);
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css"><style>.body{grid-template-rows:auto minmax(0,1fr)}tfoot td{position:sticky;bottom:0;background:#eef2f5;font-weight:700;border-top:1px solid var(--line)}
.dl{display:grid;grid-template-columns:90px 1fr 90px 1fr;border:1px solid var(--line);border-right:0;border-bottom:0}.dl>*{border-right:1px solid #d6dde3;border-bottom:1px solid #d6dde3;padding:5px 8px;min-width:0}.dl .lab{justify-content:flex-start}tbody tr.due td{background:#fff8e8}tbody tr.over td{background:#fff0ee;color:#9b2c23}</style></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small></div>
  <div class="body">
    <section class="panel"><div class="filters">
      ${dateCol?`<div class="lab">${dateCol.label||dateCol.name}</div><input id="q_from" class="field" type="date"><span>~</span><input id="q_to" class="field" type="date">`:''}
      ${textCols.map(c=>`<div class="lab">${c.label||c.name}</div><input id="q_${c.name}" class="field">`).join('')}
      <div class="lab">${pk.label||pk.name}</div><input id="q_pk" class="field">
      <button class="btn primary" onclick="search()">⌕ 검색</button><button class="btn" onclick="resetQ()">지우기</button></div></section>
    <section class="panel"><div class="cap">조회 결과 <span class="right" id="countText"></span></div>
      <div class="tablewrap"><table><thead><tr><th class="c" style="width:40px">No</th>${cols.map(c=>`<th${c.type==='num'?' class="r"':''}>${c.label||c.name}${c.formula?' ƒx':''}${c.unit?` (${c.unit})`:''}</th>`).join('')}</tr></thead><tbody id="tbody"></tbody>
      <tfoot><tr><td class="c">합계</td>${cols.map(c=>c.type==='num'?`<td class="r" id="t_${c.name}"></td>`:'<td></td>').join('')}</tr></tfoot></table></div></section>
  </div>
  <footer class="foot"><button class="btn" onclick="search()">⌕ 검색</button><button class="btn warn" onclick="delRow()">✖ 삭제</button><button class="btn" onclick="exportCsv()">▤ EXCEL</button><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">조건을 넣고 [검색]. 행 클릭 = 상세.${cols.some(c=>c.formula)?' · ƒx 항목은 조회 시 자동 계산됩니다.':''}</span></footer>
</div>
<div class="modal-bg" id="dlg"><div class="modal"><div class="t">상세 <span class="x" onclick="dlg.classList.remove('on')">×</span></div><div class="bd"><div class="dl" id="dlBody"></div></div><div class="bt"><button class="btn" onclick="dlg.classList.remove('on')">닫기</button></div></div></div>
<script>
const data=[];window.data=data;let view=[],sel=-1;
const CM=${JSON.stringify(cols)},CMAP=Object.fromEntries(CM.map(c=>[c.name,c])),F=CM.map(c=>c.name),L=Object.fromEntries(CM.map(c=>[c.name,c.label||c.name])),T=Object.fromEntries(CM.map(c=>[c.name,c.type])),PK='${pk.name}',DC=${dateCol?`'${dateCol.name}'`:'null'},TC=${JSON.stringify(textCols.map(c=>c.name))},NC=${JSON.stringify(numCols.map(c=>c.name))},ALERT=${JSON.stringify(al)};
${calcRuntimeJs()}
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const fmt=n=>(n===''||n==null)?'':Number(n).toLocaleString('ko-KR');
function msg(t){message.textContent=t}
function cell(r,f){calcApplyRow(r,CM);const c=CMAP[f],v=r[f];return c.formula?esc(calcFormat(v,c,true)):T[f]==='num'?fmt(v):T[f]==='bool'?(v?'✓':''):esc(v)}
function dueState(r){if(!ALERT.enabled||!ALERT.dateCol||!r?.[ALERT.dateCol])return '';const a=new Date(new Date().toISOString().slice(0,10)),b=new Date(r[ALERT.dateCol]);if(!Number.isFinite(+b))return '';const d=Math.ceil((b-a)/864e5);return d<0?'over':d<=ALERT.days?'due':''}
function search(){data.forEach(r=>calcApplyRow(r,CM));const f=DC?$('q_from').value:'',t=DC?$('q_to').value:'',pkq=$('q_pk').value.trim().toLowerCase();
 view=data.filter(r=>(!f||(r[DC]||'')>=f)&&(!t||(r[DC]||'')<=t)&&(!pkq||String(r[PK]??'').toLowerCase().includes(pkq))&&TC.every(c=>{const q=$('q_'+c).value.trim().toLowerCase();return !q||String(r[c]??'').toLowerCase().includes(q)}))
  .sort((a,b)=>DC?String(b[DC]).localeCompare(String(a[DC])):String(b[PK]).localeCompare(String(a[PK])));sel=-1;render();msg('조회결과 '+view.length+'건')}
function resetQ(){document.querySelectorAll('.filters input').forEach(i=>i.value='');search()}
function render(){view.forEach(r=>calcApplyRow(r,CM));tbody.innerHTML=view.length?view.map((r,i)=>'<tr class="'+(i===sel?'sel ':'')+dueState(r)+'" onclick="pick('+i+')"><td class="c">'+(i+1)+'</td>'+F.map(f=>'<td'+(T[f]==='num'?' class="r"':'')+'>'+cell(r,f)+'</td>').join('')+'</tr>').join('')
  :'<tr><td colspan="'+(F.length+1)+'" class="empty">조회 결과가 없습니다.</td></tr>';
 NC.forEach(c=>{const el=$('t_'+c);if(el)el.textContent=calcFormat(view.reduce((s,r)=>s+(Number(r[c])||0),0),CMAP[c],!!CMAP[c]?.unit)});const an=view.filter(r=>dueState(r)).length;countText.textContent=view.length+'건'+(an?' · ⏰ '+an+'건':'')}
function pick(i){sel=i;render();const r=view[i];dlBody.innerHTML=F.map(f=>'<div class="lab">'+L[f]+(CMAP[f].formula?' ƒx':'')+'</div><div>'+cell(r,f)+'</div>').join('');dlg.classList.add('on')}
function delRow(){if(sel<0)return msg('삭제할 행을 선택하세요.');const r=view[sel];dlg.classList.remove('on');if(!confirm(r[PK]+' 을(를) 삭제할까요?'))return;const i=data.findIndex(x=>x[PK]===r[PK]);if(i>=0)data.splice(i,1);search();msg(r[PK]+' 삭제했습니다.')}
function exportCsv(){data.forEach(r=>calcApplyRow(r,CM));const csv='\\ufeff'+[F.map(f=>L[f]),...view.map(r=>F.map(f=>r[f]))].map(a=>a.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='${slug(s.name)}.csv';a.click()}
document.querySelectorAll('.filters input').forEach(i=>i.addEventListener('keydown',e=>{if(e.key==='Enter')search()}));dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.classList.remove('on')});
window.MES={search,exportCsv,setMessage:msg};render();
<\/script>
<script src="mes_db.js"><\/script>
<script>MESDB.master({page:'${slug(s.name)}:data',table:'${t.name}',pk:'${pk.name}',map:${mapOf(t)},get:()=>data,render:search});<\/script>
<div id="toast"></div></body></html>
`;
}

/* ── 헤더 + 명세 화면 (전표형) ─────────────────────────────────────
   위: 헤더 입력폼(부모 테이블)  가운데: 명세 그리드(자식 테이블, 행 추가/삭제)  아래: 전표 목록 */
function masterDetailScreen(scr,parent,child,edge,loc,lookups){
 const P=colsOf(parent),C=colsOf(child),auto=autoNoConfig(parent),al=alertConfig(parent);
 const lk=linkCol(parent,child,edge);
 const pk=(P.find(c=>c.pk)||P[0]).name;
 const CC=C.filter(c=>c.name!==lk.child&&!c.pk);           /* 명세 그리드에 보일 컬럼 */
 const ckey=(C.find(c=>c.pk)||{}).name||'';
 const field=c=>c.formula?`<input id="f_${c.name}" class="field" readonly data-calc="1" title="계산식: ${esc(c.formula)}" style="background:#f3f7fb;color:#2f6fb5;font-weight:600">`:c.type==='bool'?`<div class="check"><input id="f_${c.name}" type="checkbox"></div>`
  :`<input id="f_${c.name}" class="field${c.req?' req':''}" ${c.type==='num'?'type="number"':c.type==='date'?'type="date"':''}>`;
 const pref=(pk.split('_')[0]||'no').slice(0,2).toUpperCase();
 return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${scr.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css">
<style>.body{grid-template-rows:auto minmax(120px,1fr) minmax(0,1fr)}
.grid td{padding:2px}.grid input,.grid select{width:100%;height:24px;border:1px solid #cfd6df;border-radius:3px;padding:0 5px;background:#fff}
.grid input:focus{outline:0;border-color:var(--blue)}.grid td.x{width:28px;text-align:center}
.grid .del{color:#b03a34;border:0;background:none;font-size:14px}.grid input[readonly],input[data-calc]{background:#f3f7fb;color:#2f6fb5;font-weight:600;border-color:#b9cce2}.duealert{display:none;padding:6px 9px;border:1px solid #f0c36d;background:#fff8e8;color:#8a5a00;font-weight:600}.duealert.on{display:block}.duealert.over{border-color:#e5a09a;background:#fff0ee;color:#a3261d}</style></head>
<body><div class="screen">
  <div class="title"><h1>${scr.name}</h1><small>${loc}</small></div>
  <div class="body">
    <section class="panel"><div class="cap">헤더 정보 <span class="right" id="modeTxt">신규</span></div>
      ${al.enabled&&al.dateCol?'<div id="dueAlert" class="duealert"></div>':''}<div class="formgrid" style="border-left:0;border-top:0">
${P.map(c=>`        <div class="lab">${c.label||c.name}${c.formula?' <span title="자동 계산" style="color:#2f6fb5">ƒx</span>':''}</div>${field(c)}`).join('\n')}
      </div>
      <div class="actions"><button class="btn primary" onclick="save()">▤ 저장</button><button class="btn" onclick="clearForm()">✕ 신규</button><button class="btn warn" onclick="remove()">✖ 삭제</button><button class="btn" onclick="exportCsv()">▤ EXCEL</button></div>
    </section>

    <section class="panel"><div class="cap">명세 (${child.name}) <span class="right"><button class="btn sm" onclick="addLine()">＋ 행 추가</button> &nbsp;<span id="lineCnt"></span></span></div>
      <div class="tablewrap"><table class="grid">
        <colgroup><col style="width:34px">${CC.map(()=>'<col>').join('')}<col style="width:34px"></colgroup>
        <thead><tr><th class="c">No</th>${CC.map(c=>`<th${c.type==='num'?' class="r"':''}>${c.label||c.name}${c.formula?' ƒx':''}${c.unit?` (${c.unit})`:''}</th>`).join('')}<th></th></tr></thead>
        <tbody id="lbody"></tbody>
      </table></div>
    </section>

    <section class="panel"><div class="cap">전표 목록 <span class="right"><input id="q" class="field" style="width:150px;height:22px" placeholder="검색" oninput="renderList()"> &nbsp;<span id="countText"></span></span></div>
      <div class="tablewrap"><table>
        <thead><tr>${P.map(c=>`<th${c.type==='num'?' class="r"':''}>${c.label||c.name}${c.formula?' ƒx':''}${c.unit?` (${c.unit})`:''}</th>`).join('')}<th class="c" style="width:60px">명세</th></tr></thead>
        <tbody id="tbody"></tbody>
      </table></div>
    </section>
  </div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message">헤더를 입력하고 명세 행을 추가한 뒤 [저장]. ${auto.enabled?(P.find(c=>c.pk)?.label||pk)+'를 비우면 '+autoNoPreview(parent)+' 형식으로 자동 채번됩니다.':(P.find(c=>c.pk)?.label||pk)+'는 직접 입력합니다.'}${[...P,...C].some(c=>c.formula)?' · ƒx 자동 계산':''}${al.enabled&&al.dateCol?' · 기한 '+al.days+'일 전 알림':''}</span></footer>
</div>
<script>
const rows=[];window.rows=rows;const lines=[];window.lines=lines;let sel=null,draft=[];
const PM=${JSON.stringify(P)},PMAP=Object.fromEntries(PM.map(c=>[c.name,c])),PF=PM.map(c=>c.name),PT=Object.fromEntries(PM.map(c=>[c.name,c.type])),PCALC=PM.filter(c=>c.formula).map(c=>c.name),PK='${pk}',AUTO=${JSON.stringify(auto)},ALERT=${JSON.stringify(al)};
const CM=${JSON.stringify(C)},CMAP=Object.fromEntries(CM.map(c=>[c.name,c])),CF=${JSON.stringify(CC.map(c=>c.name))},CT=Object.fromEntries(CM.map(c=>[c.name,c.type])),LINK='${lk.child}',CKEY='${ckey}';
const CREQ=PM.filter(c=>c.req&&!c.pk&&!c.formula).map(c=>c.name);
${calcRuntimeJs()}
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmt=n=>(n===''||n==null)?'':Number(n).toLocaleString('ko-KR');const today=()=>{const d=new Date(),z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,10)};
function msg(t){message.textContent=t}
function cell(r,f,T,M){const c=M[f],v=r[f];return c?.formula?esc(calcFormat(v,c,true)):T[f]==='num'?fmt(v):T[f]==='bool'?(v?'✓':''):esc(v)}
function readHead(base){const o={...(base||{})};for(const f of PF){const c=PMAP[f];if(c.formula)continue;const el=$('f_'+f);if(!el)continue;o[f]=PT[f]==='bool'?el.checked:PT[f]==='num'?(el.value===''?'':Number(el.value)):el.value}return calcApplyRow(o,PM)}
function dueState(o){if(!ALERT.enabled||!ALERT.dateCol||!o?.[ALERT.dateCol])return null;const a=new Date(today()),b=new Date(o[ALERT.dateCol]);if(!Number.isFinite(+b))return null;const d=Math.ceil((b-a)/864e5);return{days:d,kind:d<0?'over':d<=ALERT.days?'soon':'ok'}}
function renderDue(o){const el=$('dueAlert');if(!el)return;const z=dueState(o);el.className='duealert'+(z&&z.kind!=='ok'?' on'+(z.kind==='over'?' over':''):'');if(z&&z.kind==='over')el.textContent='⛔ 기한 '+Math.abs(z.days)+'일 초과';else if(z&&z.kind==='soon')el.textContent='⏰ 기한까지 '+z.days+'일 남았습니다.';else el.textContent=''}
function syncHead(o){o=o?calcApplyRow(o,PM):readHead();for(const f of PCALC){const el=$('f_'+f);if(el)el.value=calcFormat(o[f],PMAP[f],true)}renderDue(o);return o}

/* ── 명세 그리드 ── */
function renderLines(){
 draft.forEach(r=>calcApplyRow(r,CM));
 lbody.innerHTML=draft.length?draft.map((r,i)=>'<tr><td class="c">'+(i+1)+'</td>'+CF.map(f=>{const c=CMAP[f];
   if(c.formula)return '<td><input readonly data-ci="'+i+'" data-cf="'+f+'" value="'+esc(calcFormat(r[f],c,true))+'"></td>';
   return '<td>'+(CT[f]==='bool'?'<input type="checkbox" data-i="'+i+'" data-f="'+f+'" '+(r[f]?'checked':'')+'>'
    :'<input data-i="'+i+'" data-f="'+f+'" '+(CT[f]==='num'?'type="number"':CT[f]==='date'?'type="date"':'')+' value="'+esc(r[f]??'')+'">')+'</td>'}).join('')
   +'<td class="x"><button class="del" onclick="delLine('+i+')">×</button></td></tr>').join('')
  :'<tr><td colspan="'+(CF.length+2)+'" class="empty">명세가 없습니다. [＋ 행 추가]</td></tr>';
 lineCnt.textContent=draft.length+'행';
 lbody.querySelectorAll('[data-f]').forEach(el=>{const ev=el.type==='checkbox'?'change':'input';
  el.addEventListener(ev,()=>{const i=+el.dataset.i,r=draft[i],f=el.dataset.f;
   r[f]=el.type==='checkbox'?el.checked:(CT[f]==='num'?(el.value===''?'':Number(el.value)):el.value);calcApplyRow(r,CM);
   lbody.querySelectorAll('[data-ci="'+i+'"]').forEach(x=>x.value=calcFormat(r[x.dataset.cf],CMAP[x.dataset.cf],true))})});
}
function addLine(){const o={};for(const f of CF)if(!CMAP[f].formula)o[f]=CT[f]==='bool'?false:'';calcApplyRow(o,CM);draft.push(o);renderLines();
 const last=lbody.querySelectorAll('tr:last-child [data-f]');if(last.length)last[0].focus()}
function delLine(i){draft.splice(i,1);renderLines()}

/* ── 전표 목록 ── */
function renderList(){rows.forEach(r=>calcApplyRow(r,PM));lines.forEach(r=>calcApplyRow(r,CM));
 const q=($('q').value||'').trim().toLowerCase();
 const view=rows.filter(r=>!q||PF.some(f=>String(r[f]??'').toLowerCase().includes(q))).sort((a,b)=>String(b[PK]).localeCompare(String(a[PK])));
 tbody.innerHTML=view.length?view.map(r=>'<tr class="'+(r[PK]===sel?'sel':'')+'" onclick="pick(\\''+esc(String(r[PK]))+'\\')">'
   +PF.map(f=>'<td'+(PT[f]==='num'?' class="r"':'')+'>'+cell(r,f,PT,PMAP)+'</td>').join('')
   +'<td class="c">'+lines.filter(l=>String(l[LINK])===String(r[PK])).length+'</td></tr>').join('')
  :'<tr><td colspan="'+(PF.length+1)+'" class="empty">등록된 전표가 없습니다.</td></tr>';
 countText.textContent=view.length+'건';
}
function pick(k){
 const r=rows.find(x=>String(x[PK])===k);if(!r)return;calcApplyRow(r,PM);sel=r[PK];
 PF.forEach(f=>{const el=$('f_'+f);if(!el)return;const c=PMAP[f];if(c.formula)el.value=calcFormat(r[f],c,true);else if(PT[f]==='bool')el.checked=!!r[f];else el.value=r[f]??''});
 draft=lines.filter(l=>String(l[LINK])===String(sel)).map(l=>{const o={};for(const f of CF)o[f]=l[f];o.__k=l[CKEY];calcApplyRow(o,CM);return o});
 modeTxt.textContent='수정: '+k;renderLines();renderList();msg(k+' 을(를) 불러왔습니다. (명세 '+draft.length+'행)');
}
function clearForm(){sel=null;PF.forEach(f=>{const el=$('f_'+f),c=PMAP[f];if(!el||c.formula)return;if(PT[f]==='bool')el.checked=false;else el.value=PT[f]==='date'&&!/due|deadline|approved|reviewed|closed|completed|next_|updated_at/i.test(f)?today():''});
 syncHead();draft=[];modeTxt.textContent='신규';renderLines();renderList();msg('새 전표를 입력하세요.');$('f_'+PK)?.focus()}
function autoDate(){const z=today().replaceAll('-','');return AUTO.date==='YYYYMMDD'?z:AUTO.date==='YYMMDD'?z.slice(2):AUTO.date==='YYMM'?z.slice(2,6):AUTO.date==='YYYY'?z.slice(0,4):''}
function nextNo(){if(!AUTO.enabled)return '';const base=[AUTO.prefix,autoDate()].filter(Boolean).join(AUTO.sep),p=base?base+AUTO.sep:'';const n=rows.filter(r=>String(r[PK]).startsWith(p)).map(r=>Number(String(r[PK]).slice(p.length))||0);
 return p+String((n.length?Math.max(...n):0)+1).padStart(AUTO.digits,'0')}
function nextLineKey(base,i){return base+'-'+String(i+1).padStart(2,'0')}

function save(){
 for(const f of CREQ){const el=$('f_'+f);if(el&&PT[f]!=='bool'&&!String(el.value).trim())return msg((el.previousElementSibling?.textContent||f)+' 은(는) 필수입니다.')}
 if(!draft.length)return msg('명세를 한 행 이상 입력하세요.');
 let no=String($('f_'+PK).value||'').trim();if(!no){if(AUTO.enabled)no=nextNo();else return msg((PMAP[PK]?.label||PK)+' 을(를) 입력하세요.')}
 const head=readHead();head[PK]=no;calcApplyRow(head,PM);
 if(sel&&sel!==no){const i=rows.findIndex(r=>r[PK]===sel);if(i>=0)rows.splice(i,1);
  for(let i=lines.length-1;i>=0;i--)if(String(lines[i][LINK])===String(sel))lines.splice(i,1)}
 const i=rows.findIndex(r=>r[PK]===no);if(i>=0)rows[i]=head;else rows.push(head);
 for(let k=lines.length-1;k>=0;k--)if(String(lines[k][LINK])===String(no))lines.splice(k,1);
 draft.forEach((r,idx)=>{const o={...r};delete o.__k;o[LINK]=no;calcApplyRow(o,CM);${ckey?"o[CKEY]=r.__k||nextLineKey(no,idx);":""}lines.push(o)});
 sel=no;$('f_'+PK).value=no;syncHead(head);modeTxt.textContent='수정: '+no;renderLines();renderList();
 msg(no+' 저장했습니다. (명세 '+draft.length+'행)');
}
function remove(){
 if(!sel)return msg('삭제할 전표를 목록에서 선택하세요.');
 if(!confirm(sel+' 전표와 명세를 모두 삭제할까요?'))return;
 const i=rows.findIndex(r=>r[PK]===sel);if(i>=0)rows.splice(i,1);
 for(let k=lines.length-1;k>=0;k--)if(String(lines[k][LINK])===String(sel))lines.splice(k,1);
 const key=sel;clearForm();msg(key+' 삭제했습니다.');
}
function exportCsv(){rows.forEach(r=>calcApplyRow(r,PM));lines.forEach(r=>calcApplyRow(r,CM));
 const h=[...${JSON.stringify(P.map(c=>c.label||c.name))},...${JSON.stringify(CC.map(c=>c.label||c.name))}];
 const body=[];for(const r of rows){const ls=lines.filter(l=>String(l[LINK])===String(r[PK]));
  if(!ls.length)body.push([...PF.map(f=>r[f]),...CF.map(()=>'')]);
  else for(const l of ls)body.push([...PF.map(f=>r[f]),...CF.map(f=>l[f])])}
 const csv='\\ufeff'+[h,...body].map(a=>a.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\\n');
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='${slug(scr.name)}.csv';a.click();
}
PF.filter(f=>!PMAP[f].formula).forEach(f=>{const el=$('f_'+f);if(el)el.addEventListener(PT[f]==='bool'?'change':'input',()=>syncHead())});
window.MES={search:renderList,save,setMessage:msg};clearForm();
<\/script>
<script src="mes_db.js"><\/script>
<script>
MESDB.master({page:'${slug(scr.name)}:rows',table:'${parent.name}',pk:'${pk}',map:${mapOf(parent)},get:()=>rows,render:()=>{rows.forEach(r=>calcApplyRow(r,PM));renderList();if(sel&&!rows.some(r=>r[PK]===sel))clearForm()}});
MESDB.master({page:'${slug(scr.name)}:lines',table:'${child.name}',pk:'${ckey||lk.child}',map:${mapOf(child)},get:()=>lines,render:()=>{lines.forEach(r=>calcApplyRow(r,CM));if(sel)pick(String(sel));renderList()}});
<\/script>
<div id="toast"></div></body></html>
`;
}
function blankScreen(s,loc){return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${s.name}</title>
<script src="app_config.js"><\/script><link rel="stylesheet" href="mes_screen.css"></head>
<body><div class="screen">
  <div class="title"><h1>${s.name}</h1><small>${loc}</small></div>
  <div class="body"><section class="panel"><div class="cap">${s.name}</div><div class="empty">이 화면은 아직 내용이 없습니다.<br>sample_input.html / sample_status.html 을 참고해 채우세요.</div></section></div>
  <footer class="foot"><button class="btn" onclick="window.parent?.closeActive?.()">⊠ 닫기</button><span class="msg" id="message"></span></footer>
</div></body></html>
`}
function relationsDoc(){
 let s=`# 시스템 관계 정리 (${new Date().toLocaleString('ko-KR')})\n\n## 메뉴 계층\n`;
 const kids=(id,k)=>D.edges.filter(e=>e.from===id&&e.kind===k).map(e=>({n:N(e.to),e})).filter(x=>x.n);
 for(const m of D.nodes.filter(n=>n.type==='module')){s+=`- ${m.name}\n`;for(const{n:sec} of kids(m.id,'contains')){s+=`  - ${sec.name}\n`;for(const{n:sc} of kids(sec.id,'contains'))s+=`    - ${sc.name} (${sc.meta.file||'-'}, ${sc.meta.kind})\n`}}
 s+=`\n## 화면 → 테이블 (사용)\n`;for(const e of D.edges.filter(e=>e.kind==='uses'))s+=`- ${N(e.from)?.name} → ${N(e.to)?.name}${e.label?' : '+e.label:''}\n`;
 s+=`\n## 테이블 → 테이블 (참조)\n`;for(const e of D.edges.filter(e=>e.kind==='ref'))s+=`- ${N(e.from)?.name} → ${N(e.to)?.name}${e.label?' : '+e.label:''}\n`;
 s+=`\n## 화면 흐름\n`;for(const e of D.edges.filter(e=>e.kind==='flow'))s+=`- ${N(e.from)?.name} → ${N(e.to)?.name}${e.label?' : '+e.label:''}\n`;
 s+=`\n## 테이블 정의\n`;for(const t of D.nodes.filter(n=>n.type==='table')){s+=`### ${t.name}\n| 컬럼 | 라벨 | 형 | PK | 필수 | 계산식 | 단위 | DB저장 |\n|---|---|---|---|---|---|---|---|\n`;for(const c of colsOf(t))s+=`| ${c.name} | ${c.label||''} | ${c.type} | ${c.pk?'✓':''} | ${c.req?'✓':''} | ${String(c.formula||'').replace(/\|/g,'\\|')} | ${c.unit||''} | ${c.formula?(c.calcStore?'✓':'화면계산'):''} |\n`;s+='\n'}
 return s;
}
function showGen(){
 const names=Object.keys(GEN);genCur=names[0];
 $('genFiles').innerHTML=names.map(n=>`<button class="${n===genCur?'on':''}" data-f="${esc(n)}">${esc(n)}<small>${(GEN[n].length/1024).toFixed(1)}k</small></button>`).join('');
 $('genFiles').querySelectorAll('button').forEach(b=>b.onclick=()=>{genCur=b.dataset.f;showGen()});
 $('genView').textContent=GEN[genCur];$('genMsg').textContent=`${names.length}개 파일 생성.${GEN['건너뛴_화면.txt']?' 🔒 잠근 화면은 제외됨.':''} [단일 index.html] 은 한 파일로, [ZIP] 은 파일별로.`;
 genDlg.classList.add('on');
}

